-- SOURCE_ONLY corrected UNRELEASED169 proposal for a fresh intact168 clone.
-- Never apply to the historical failed169 clone; original e5a8/history stay literal.
-- Genuine manual OFF PW/RW parent. No COUNT/PZ/149 surrogate or WMS mutation.
SET LOCAL TimeZone='UTC';
DO $$BEGIN
 IF current_user<>session_user OR to_regclass('public.catalog_stock_control_manifest') IS NULL
 OR to_regprocedure('public.parcel_physical_wz_valid()') IS NULL THEN RAISE EXCEPTION '169 owner/predecessor unavailable' USING ERRCODE='55000';END IF;
 IF current_user<>(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='public.catalog_stock_control_manifest'::regclass)
 OR NOT public.catalog_stock_control_guards() OR NOT public.parcel_physical_wz_valid()
 OR NOT public.financial_return_guards() OR NOT public.buyer_address_guards() OR NOT public.operative_delivery_valid()
 OR NOT EXISTS(SELECT FROM migrations WHERE name='168_physical_parcel_wz')
 OR EXISTS(SELECT FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'manual_inventory_off_'))
 OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'manual_inventory_off_'))
 OR EXISTS(SELECT FROM migrations WHERE name='169_manual_inventory_off') THEN RAISE EXCEPTION '169 requires intact168/no remnants' USING ERRCODE='55000';END IF;
END $$;
LOCK TABLE catalog_stock_control_manifest IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE manual_inventory_off_install_basis ON COMMIT DROP AS SELECT
 pg_current_xact_id()::text root_xid,transaction_timestamp() start_at,pg_backend_pid() backend_pid,
 current_user::text owner_name,to_jsonb(m) original152_manifest,catalog_stock_control_fingerprint() predecessor_fingerprint,
 NULL::jsonb changed_functions,b2b_credit_fingerprint() original160_fingerprint,
 NULL::jsonb projected_functions FROM catalog_stock_control_manifest m;
REVOKE ALL ON pg_temp.manual_inventory_off_install_basis FROM PUBLIC,dyna_app;

CREATE FUNCTION manual_inventory_off_hash(j jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$SELECT encode(sha256(convert_to(j::text,'UTF8')),'hex')$$;
CREATE TABLE manual_inventory_off_series(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,warehouse_id uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN('PW','RW')),version bigint NOT NULL DEFAULT 1 CHECK(version=1),
 prefix text NOT NULL CHECK(prefix=kind||'-M'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,warehouse_id,kind),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE manual_inventory_off_counters(
 tenant_id uuid NOT NULL,series_id uuid NOT NULL,year integer NOT NULL CHECK(year BETWEEN 2000 AND 9999),value bigint NOT NULL CHECK(value>0),
 PRIMARY KEY(tenant_id,series_id,year),FOREIGN KEY(tenant_id,series_id) REFERENCES manual_inventory_off_series(tenant_id,id));
CREATE TABLE manual_inventory_off_previews(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,
 client_key uuid NOT NULL,request jsonb NOT NULL,scope_hash text NOT NULL CHECK(scope_hash~'^[a-f0-9]{64}$'),
 frame jsonb NOT NULL,projection jsonb NOT NULL,year integer NOT NULL CHECK(year BETWEEN 2000 AND 9999),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,
 CHECK(expires_at=created_at+interval '15 minutes'),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
CREATE TABLE manual_inventory_off_admissions(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,preview_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,
 client_key uuid NOT NULL,request jsonb NOT NULL,root_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 strict_effect_id uuid,UNIQUE(tenant_id,id),UNIQUE(tenant_id,preview_id),UNIQUE(tenant_id,client_key),
 FOREIGN KEY(tenant_id,preview_id) REFERENCES manual_inventory_off_previews(tenant_id,id),
 FOREIGN KEY(tenant_id,strict_effect_id) REFERENCES catalog_stock_control_effect_admissions(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
CREATE TABLE manual_inventory_off_receipts(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,preview_id uuid NOT NULL,client_key uuid NOT NULL,
 series_id uuid NOT NULL,year integer NOT NULL,sequence bigint NOT NULL CHECK(sequence>0),
 stock_movement_id uuid NOT NULL,location_movement_id uuid NOT NULL,payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,preview_id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,series_id,year,sequence),
 FOREIGN KEY(tenant_id,id) REFERENCES manual_inventory_off_admissions(tenant_id,id),
 FOREIGN KEY(tenant_id,preview_id) REFERENCES manual_inventory_off_previews(tenant_id,id),
 FOREIGN KEY(tenant_id,series_id) REFERENCES manual_inventory_off_series(tenant_id,id),
 FOREIGN KEY(tenant_id,stock_movement_id) REFERENCES stock_movements(tenant_id,id),
 FOREIGN KEY(tenant_id,location_movement_id) REFERENCES stock_location_movements(tenant_id,id));
CREATE INDEX manual_inventory_off_receipts_page ON manual_inventory_off_receipts(tenant_id,created_at DESC,id DESC);
CREATE TABLE manual_inventory_off_certificate(id boolean PRIMARY KEY DEFAULT true CHECK(id),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'));

CREATE FUNCTION manual_inventory_off_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN RAISE EXCEPTION 'Sealed manual OFF history' USING ERRCODE='23514';END$$;
DO $$DECLARE r record;BEGIN FOR r IN SELECT relname FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'manual_inventory_off_') AND relkind='r' LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',r.relname);
 EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',r.relname);
 IF r.relname<>'manual_inventory_off_certificate' THEN EXECUTE format('CREATE POLICY tenant_scope ON public.%I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',r.relname)
;END IF;
 EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,dyna_app',r.relname);
 IF r.relname IN('manual_inventory_off_series','manual_inventory_off_previews','manual_inventory_off_receipts','manual_inventory_off_certificate') THEN
 EXECUTE format('CREATE TRIGGER manual_inventory_off_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.manual_inventory_off_immutable()',r.relname);END IF;
 END LOOP;END$$;

-- Original HTTP credential is captured by the trusted server, not accepted in a body.
-- Stock administrators; API requires inventory read+write, never orders scopes.
CREATE FUNCTION manual_inventory_off_identity(t uuid,u uuid,k uuid,h text,r text,w boolean,pin boolean) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE x record;BEGIN
 IF t IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid THEN RAISE EXCEPTION 'Manual OFF tenant changed' USING ERRCODE='42501';END IF;
 IF pin THEN PERFORM 1 FROM users WHERE id=u FOR SHARE;PERFORM 1 FROM tenants WHERE id=t FOR SHARE;
 PERFORM 1 FROM account_security WHERE user_id=u FOR SHARE;PERFORM 1 FROM workspace_security_policies WHERE tenant_id=t FOR SHARE;
 PERFORM 1 FROM memberships WHERE(tenant_id,user_id)=(t,u) FOR SHARE;
 IF k IS NULL THEN PERFORM 1 FROM sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;
 ELSE PERFORM 1 FROM api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;END IF;END IF;
 IF k IS NULL THEN SELECT m.role,CASE WHEN coalesce(p.require_mfa,false) THEN least(s.expires_at,s.mfa_verified_at+interval '8 hours') ELSE s.expires_at END deadline,
 coalesce(p.require_mfa,false) AND NOT coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at>clock_timestamp()-interval '8 hours',false) mfa_required,true scope_ok
 INTO x FROM sessions s JOIN users z ON z.id=s.user_id JOIN tenants n ON n.id=s.tenant_id JOIN memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)
 LEFT JOIN account_security a ON a.user_id=z.id LEFT JOIN workspace_security_policies p ON p.tenant_id=n.id
 WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>clock_timestamp() AND s.account_version=coalesce(a.version,0);
 ELSE SELECT m.role,k0.expires_at deadline,coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required,
 k0.scopes@>CASE WHEN w THEN ARRAY['inventory:read','inventory:write']::text[] ELSE ARRAY['inventory:read']::text[] END scope_ok
 INTO x FROM api_keys k0 JOIN users z ON z.id=k0.user_id JOIN tenants n ON n.id=k0.tenant_id JOIN memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)
 LEFT JOIN account_security a ON a.user_id=z.id LEFT JOIN workspace_security_policies p ON p.tenant_id=n.id
 WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>clock_timestamp();END IF;
 IF x.role IS NULL THEN RAISE EXCEPTION 'Expired manual OFF authority' USING ERRCODE='28000';END IF;
 IF x.role<>r THEN RAISE EXCEPTION 'Manual OFF role changed' USING ERRCODE='40001';END IF;
 IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>'admin') THEN RAISE EXCEPTION 'Missing manual OFF authority' USING ERRCODE='42501';END IF;
 RETURN to_jsonb(x);END$$;

CREATE FUNCTION manual_inventory_off_require() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF NOT manual_inventory_off_valid() THEN RAISE EXCEPTION 'Incomplete manual OFF family' USING ERRCODE='55000';END IF;END$$;

CREATE FUNCTION manual_inventory_off_frame(pid uuid,wh uuid,locking boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p public.products;w public.warehouses;s public.stock;policy jsonb;bins jsonb;holds jsonb;raw jsonb;src jsonb;series jsonb;
BEGIN
 PERFORM manual_inventory_off_require();
 IF locking THEN policy:=warehouse_inventory_policy_lock(t,wh);ELSE policy:=warehouse_inventory_policy(t,wh);END IF;
 IF policy->>'usage'<>'sale' OR policy->'enabled'<>'true'::jsonb THEN RAISE EXCEPTION 'Manual correction requires active sale warehouse' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM wms_policies WHERE tenant_id=t AND enabled) THEN RAISE EXCEPTION 'Use genuine WMS correction parent' USING ERRCODE='23514';END IF;
 IF locking THEN SELECT * INTO p FROM products WHERE(tenant_id,id)=(t,pid) FOR SHARE;SELECT * INTO w FROM warehouses WHERE(tenant_id,id)=(t,wh) FOR SHARE;
 SELECT * INTO s FROM stock WHERE(tenant_id,warehouse_id,product_id)=(t,wh,pid) FOR UPDATE;
 PERFORM 1 FROM stock_locations WHERE(tenant_id,warehouse_id,product_id)=(t,wh,pid) ORDER BY location COLLATE "C" FOR UPDATE;
 -- Freeze actual allocation scan/state fields through the final IAM waits. Native parcel writers use stock -> reservation -> location order.
 PERFORM 1 FROM reservations r WHERE(r.tenant_id,r.warehouse_id,r.product_id)=(t,wh,pid) ORDER BY r.order_id FOR SHARE;
 PERFORM 1 FROM reservation_locations q WHERE(q.tenant_id,q.warehouse_id,q.product_id)=(t,wh,pid) ORDER BY q.order_id,q.location COLLATE "C" FOR SHARE;
 ELSE SELECT * INTO p FROM products WHERE(tenant_id,id)=(t,pid);SELECT * INTO w FROM warehouses WHERE(tenant_id,id)=(t,wh);SELECT * INTO s FROM stock WHERE(tenant_id,warehouse_id,product_id)=(t,wh,pid);END IF;
 IF p.id IS NULL OR w.id IS NULL OR s.product_id IS NULL THEN RAISE EXCEPTION 'Own physical cell missing' USING ERRCODE='P0002';END IF;
 IF p.kind<>'simple' OR EXISTS(SELECT FROM bundle_components WHERE tenant_id=t AND bundle_id=pid) THEN RAISE EXCEPTION 'Manual correction supports genuine simple physical product' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT FROM stock_locations WHERE(tenant_id,warehouse_id,product_id,location)=(t,wh,pid,s.location)) THEN RAISE EXCEPTION 'Existing default bin required' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.order_id,a.location),'[]') INTO holds FROM reservation_locations a JOIN reservations z USING(tenant_id,order_id,product_id,warehouse_id) WHERE(a.tenant_id,a.warehouse_id,a.product_id)=(t,wh,pid) AND z.state='active';
 SELECT coalesce(jsonb_agg(jsonb_build_object('location',b.location,'quantity',b.quantity,'reserved',coalesce(q.n,0),'available',b.quantity-coalesce(q.n,0)) ORDER BY b.location COLLATE "C"),'[]') INTO bins FROM stock_locations b
 LEFT JOIN LATERAL(SELECT sum(a.quantity-coalesce(a.consumed_quantity,0)) n FROM reservation_locations a JOIN reservations z USING(tenant_id,order_id,product_id,warehouse_id) WHERE(a.tenant_id,a.warehouse_id,a.product_id,a.location)=(t,wh,pid,b.location) AND z.state='active') q ON true WHERE(b.tenant_id,b.warehouse_id,b.product_id)=(t,wh,pid);
 IF jsonb_array_length(bins)>1000 OR jsonb_array_length(holds)>10000 THEN RAISE EXCEPTION 'Whole manual source budget' USING ERRCODE='54000';END IF;
 SELECT jsonb_build_object('PW',(SELECT jsonb_build_object('series_id',id,'version',version::text) FROM manual_inventory_off_series WHERE(tenant_id,warehouse_id,kind)=(t,wh,'PW')),
 'RW',(SELECT jsonb_build_object('series_id',id,'version',version::text) FROM manual_inventory_off_series WHERE(tenant_id,warehouse_id,kind)=(t,wh,'RW'))) INTO series;
 src:=jsonb_build_object('protocol','manual_off_pw_rw_v1','product',jsonb_build_object('id',pid,'sku',p.sku,'name',p.name,'catalog_id',p.catalog_id),
 'warehouse',jsonb_build_object('id',wh,'name',w.name,'code',w.code,'inventory_policy_version',policy->'version'),
 'wms_policy',jsonb_build_object('enabled',false,'version',coalesce((SELECT version::text FROM wms_policies WHERE tenant_id=t),'0')),
 'stock',jsonb_build_object('version',s.version::text,'on_hand',s.on_hand,'reserved',s.reserved,'available',s.available,'default_location',s.location),'bins',bins,'numbering',series);
 raw:=jsonb_build_object('product',to_jsonb(p),'warehouse',to_jsonb(w),'stock',to_jsonb(s),'bins',(SELECT jsonb_agg(to_jsonb(b) ORDER BY b.location COLLATE "C") FROM stock_locations b WHERE(b.tenant_id,b.warehouse_id,b.product_id)=(t,wh,pid)),
 'allocations',holds,'warehouse_policy',policy,'wms_policy',(SELECT to_jsonb(h) FROM wms_policies h WHERE h.tenant_id=t),'numbering',series);
 IF octet_length(raw::text)>4194304 THEN RAISE EXCEPTION 'Whole manual source byte budget' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('raw',raw,'source',src||jsonb_build_object('revision',manual_inventory_off_hash(raw)));END$$;

CREATE FUNCTION manual_inventory_off_projection(f jsonb,b jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$
DECLARE d integer;bin jsonb;s jsonb:=f#>'{source,stock}';v jsonb;BEGIN
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Manual request must be object' USING ERRCODE='23514';END IF;
 IF (b-ARRAY['client_key','revision','product_id','warehouse_id','location','delta','note'])<>'{}'
 OR(SELECT count(*) FROM jsonb_object_keys(b))<>7 OR jsonb_typeof(b->'delta') IS DISTINCT FROM 'number'
 OR NOT coalesce(b->>'delta'~'^-?[1-9][0-9]{0,6}$',false) OR length(b->>'location') NOT BETWEEN 1 AND 100
 OR length(b->>'note') NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'Invalid complete manual request' USING ERRCODE='23514';END IF;
 d:=(b->>'delta')::integer;IF abs(d)>1000000 THEN RAISE EXCEPTION 'Manual delta bound' USING ERRCODE='23514';END IF;
 SELECT x INTO bin FROM jsonb_array_elements(f#>'{source,bins}') x WHERE x->>'location'=b->>'location';
 IF bin IS NULL OR (s->>'on_hand')::bigint+d NOT BETWEEN 0 AND 2147483647 OR(bin->>'quantity')::bigint+d NOT BETWEEN 0 AND 2147483647
 OR(s->>'available')::bigint+d<0 OR(bin->>'available')::bigint+d<0 THEN RAISE EXCEPTION 'Manual correction cannot consume active holds' USING ERRCODE='23514';END IF;
 v:=jsonb_build_object('state','unknown','quantity',abs(d),'unit_cost_minor',NULL,'value_minor',NULL,'currency',NULL);
 RETURN jsonb_build_object('kind',CASE WHEN d>0 THEN 'PW' ELSE 'RW' END,'quantity',abs(d),'location',b->'location',
 'stock_before',s,'stock_after',s||jsonb_build_object('on_hand',(s->>'on_hand')::integer+d,'available',(s->>'available')::integer+d,'version',((s->>'version')::bigint+1)::text),
 'bin_before',bin,'bin_after',bin||jsonb_build_object('quantity',(bin->>'quantity')::integer+d,'available',(bin->>'available')::integer+d),'valuation',v);END$$;

CREATE FUNCTION manual_inventory_off_preview_view(pid uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
 SELECT jsonb_build_object('id',p.id,'client_key',p.client_key,'request',p.request,'scope_hash',p.scope_hash,'source',p.frame->'source','projection',p.projection,
 'created_at',to_char(p.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(p.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'receipt_id',(SELECT id FROM manual_inventory_off_receipts r WHERE(r.tenant_id,r.preview_id)=(p.tenant_id,p.id))) FROM manual_inventory_off_previews p WHERE(p.tenant_id,p.id)=(nullif(current_setting('app.tenant_id',true),'')::uuid,pid)$$;
CREATE FUNCTION manual_inventory_off_preview_can_apply(pid uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE p public.manual_inventory_off_previews;BEGIN SELECT * INTO p FROM manual_inventory_off_previews WHERE(tenant_id,id)=(nullif(current_setting('app.tenant_id',true),'')::uuid,pid);
 IF p.id IS NULL OR clock_timestamp()>=p.expires_at OR extract(year FROM clock_timestamp())<>p.year OR EXISTS(SELECT FROM manual_inventory_off_receipts WHERE(tenant_id,preview_id)=(p.tenant_id,pid)) THEN RETURN false;END IF;
 RETURN p.frame=manual_inventory_off_frame((p.request->>'product_id')::uuid,(p.request->>'warehouse_id')::uuid,false);
 EXCEPTION WHEN check_violation OR no_data_found THEN RETURN false;END$$;
CREATE FUNCTION manual_inventory_off_preview(u uuid,k uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p public.manual_inventory_off_previews;f jsonb;projection jsonb;nowat timestamptz:=clock_timestamp();BEGIN
 PERFORM manual_inventory_off_require();
 PERFORM warehouse_inventory_policy_lock(t,(b->>'warehouse_id')::uuid);
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog.strict.quota:'||t,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('manual.off.quota:'||t,0));
 SELECT * INTO p FROM manual_inventory_off_previews WHERE(tenant_id,client_key)=(t,(b->>'client_key')::uuid);
 IF p.id IS NOT NULL THEN IF p.actor_id<>u OR p.api_key_id IS DISTINCT FROM k OR p.request<>b THEN RAISE EXCEPTION 'Manual preview key conflict' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('preview',manual_inventory_off_preview_view(p.id),'reused',true);END IF;
 f:=manual_inventory_off_frame((b->>'product_id')::uuid,(b->>'warehouse_id')::uuid,true);
 IF f#>>'{source,revision}' IS DISTINCT FROM b->>'revision' THEN RAISE EXCEPTION 'Manual source changed' USING ERRCODE='40001';END IF;
 projection:=manual_inventory_off_projection(f,b);
 INSERT INTO manual_inventory_off_previews(id,tenant_id,actor_id,api_key_id,client_key,request,scope_hash,frame,projection,year,created_at,expires_at)
 VALUES(gen_random_uuid(),t,u,k,(b->>'client_key')::uuid,b,manual_inventory_off_hash(jsonb_build_object('request',b,'frame',f,'projection',projection)),f,projection,extract(year FROM nowat),nowat,nowat+interval '15 minutes') RETURNING * INTO p;
 RETURN jsonb_build_object('preview',manual_inventory_off_preview_view(p.id),'reused',false);END$$;

-- Same-XID closure validates the *historical* before/after document and both real
-- native journals. No current-stock dependency in restored history validation.
CREATE FUNCTION manual_inventory_off_validate(rid uuid,live boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;a public.manual_inventory_off_admissions;p public.manual_inventory_off_previews;r public.manual_inventory_off_receipts;s public.manual_inventory_off_series;sm public.stock_movements;bm public.stock_location_movements;doc jsonb;d integer;BEGIN
 SELECT * INTO a FROM manual_inventory_off_admissions WHERE(tenant_id,id)=(t,rid);SELECT * INTO r FROM manual_inventory_off_receipts WHERE(tenant_id,id)=(t,rid);
 SELECT * INTO p FROM manual_inventory_off_previews WHERE(tenant_id,id)=(t,a.preview_id);SELECT * INTO s FROM manual_inventory_off_series WHERE(tenant_id,id)=(t,r.series_id);
 IF a.id IS NULL OR r.id IS NULL OR p.id IS NULL OR s.id IS NULL OR(a.preview_id,a.client_key) IS DISTINCT FROM(r.preview_id,r.client_key)
 OR(p.actor_id,p.api_key_id) IS DISTINCT FROM(a.actor_id,a.api_key_id) OR a.request<>jsonb_build_object('client_key',a.client_key,'scope_hash',p.scope_hash,'confirmed',true)
 OR p.scope_hash<>manual_inventory_off_hash(jsonb_build_object('request',p.request,'frame',p.frame,'projection',p.projection))
 OR p.projection<>manual_inventory_off_projection(p.frame,p.request) THEN RAISE EXCEPTION 'Incomplete manual OFF closure' USING ERRCODE='23514';END IF;
 d:=(p.request->>'delta')::integer;SELECT * INTO sm FROM stock_movements WHERE(tenant_id,id)=(t,r.stock_movement_id);SELECT * INTO bm FROM stock_location_movements WHERE(tenant_id,id)=(t,r.location_movement_id);
 IF sm.id IS NULL OR bm.id IS NULL OR(sm.product_id,sm.warehouse_id,sm.delta,sm.kind,sm.note) IS DISTINCT FROM((p.request->>'product_id')::uuid,(p.request->>'warehouse_id')::uuid,d,'manual_off_correction',p.request->>'note')
 OR(sm.product_id,sm.warehouse_id,sm.delta,sm.kind,sm.note) IS DISTINCT FROM(bm.product_id,bm.warehouse_id,bm.delta,bm.kind,bm.note)
 OR sm.order_id IS NOT NULL OR sm.warehouse_document_id IS NOT NULL OR sm.stocktake_id IS NOT NULL OR bm.order_id IS NOT NULL OR bm.stocktake_id IS NOT NULL
 OR bm.operation_id<>rid OR bm.location<>p.request->>'location' THEN RAISE EXCEPTION 'Manual document not backed by exact native journals' USING ERRCODE='23514';END IF;
 doc:=jsonb_build_object('id',rid,'number',s.prefix||'/'||r.year||'/'||CASE WHEN length(r.sequence::text)>=6 THEN r.sequence::text ELSE lpad(r.sequence::text,6,'0') END,
 'kind',s.kind,'series_id',s.id,'year',r.year,'sequence',r.sequence::text,'warehouse_id',s.warehouse_id,
 'rows',jsonb_build_array(jsonb_build_object('ordinal',0,'product_id',p.request->'product_id','sku',p.frame#>'{source,product,sku}','name',p.frame#>'{source,product,name}',
 'location',p.request->'location','delta',d,'quantity',abs(d))),'valuation',p.projection->'valuation');
 IF s.kind<>p.projection->>'kind' OR s.warehouse_id<>(p.request->>'warehouse_id')::uuid OR r.year<>p.year OR r.payload<>jsonb_build_object('id',rid,'preview_id',p.id,'client_key',a.client_key,
 'protocol','manual_off_pw_rw_v1','request',p.request,'scope_hash',p.scope_hash,'source',p.frame->'source','projection',p.projection,'document',doc,
 'journals',jsonb_build_object('stock_movement_id',sm.id,'location_movement_id',bm.id),'created_at',to_char(r.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
 THEN RAISE EXCEPTION 'Manual immutable document differs' USING ERRCODE='23514';END IF;
 IF live THEN
 IF a.root_xid<>pg_current_xact_id() OR NOT EXISTS(SELECT FROM stock_movements j WHERE(j.tenant_id,j.id)=(t,sm.id) AND catalog_stock_control_owns_xmin(j.xmin)) OR NOT EXISTS(SELECT FROM stock_location_movements j WHERE(j.tenant_id,j.id)=(t,bm.id) AND catalog_stock_control_owns_xmin(j.xmin))
 OR NOT EXISTS(SELECT FROM stock x WHERE(x.tenant_id,x.warehouse_id,x.product_id)=(t,sm.warehouse_id,sm.product_id) AND to_jsonb(x)=(p.frame#>'{raw,stock}')||jsonb_build_object('on_hand',(p.frame#>>'{raw,stock,on_hand}')::integer+d,'available',(p.frame#>>'{raw,stock,available}')::integer+d,'version',((p.frame#>>'{raw,stock,version}')::bigint+1)))
 THEN RAISE EXCEPTION 'Manual stock/XID effect differs' USING ERRCODE='23514';END IF;
 IF (SELECT jsonb_agg(to_jsonb(q) ORDER BY q.location COLLATE "C") FROM stock_locations q WHERE(q.tenant_id,q.warehouse_id,q.product_id)=(t,sm.warehouse_id,sm.product_id)) IS DISTINCT FROM
 (SELECT jsonb_agg(CASE WHEN q->>'location'=bm.location THEN q||jsonb_build_object('quantity',(q->>'quantity')::integer+d) ELSE q END ORDER BY q->>'location' COLLATE "C") FROM jsonb_array_elements(p.frame#>'{raw,bins}') q)
 OR (SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.order_id,q.location),'[]') FROM reservation_locations q JOIN reservations z USING(tenant_id,order_id,product_id,warehouse_id) WHERE(q.tenant_id,q.warehouse_id,q.product_id)=(t,sm.warehouse_id,sm.product_id) AND z.state='active') IS DISTINCT FROM p.frame#>'{raw,allocations}'
 THEN RAISE EXCEPTION 'Manual bin/holds effect differs' USING ERRCODE='23514';END IF;

 IF a.strict_effect_id IS NOT NULL AND NOT EXISTS(SELECT FROM catalog_stock_control_effect_admissions e WHERE(e.tenant_id,e.id,e.source_kind,e.source_id,e.actor_id)=(t,a.strict_effect_id,'manual_off_correction',rid,a.actor_id) AND e.api_key_id IS NOT DISTINCT FROM a.api_key_id AND e.txid=a.root_xid AND e.sealed) THEN RAISE EXCEPTION 'Manual strict effect not sealed' USING ERRCODE='23514';END IF;
 END IF;END$$;

CREATE FUNCTION manual_inventory_off_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 PERFORM manual_inventory_off_validate(NEW.id,true);RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER manual_inventory_off_complete AFTER INSERT ON manual_inventory_off_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION manual_inventory_off_complete();
CREATE FUNCTION manual_inventory_off_counter_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE n bigint;v bigint;BEGIN
 SELECT max(sequence) INTO n FROM manual_inventory_off_receipts WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year);
 SELECT value INTO v FROM manual_inventory_off_counters WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year);
 IF n IS DISTINCT FROM v OR v<>(SELECT count(*) FROM manual_inventory_off_receipts WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year)) THEN RAISE EXCEPTION 'Manual counter/document closure' USING ERRCODE='23514';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER manual_inventory_off_counter_complete AFTER INSERT OR UPDATE ON manual_inventory_off_counters DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION manual_inventory_off_counter_complete();
CREATE FUNCTION manual_inventory_off_admission_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Immutable manual admission' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND (OLD.root_xid<>pg_current_xact_id() OR OLD.strict_effect_id IS NOT NULL OR NEW.strict_effect_id IS NULL OR(to_jsonb(NEW)-'strict_effect_id')<>(to_jsonb(OLD)-'strict_effect_id')) THEN RAISE EXCEPTION 'Only native first strict binding permitted' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER manual_inventory_off_admission_guard BEFORE UPDATE OR DELETE ON manual_inventory_off_admissions FOR EACH ROW EXECUTE FUNCTION manual_inventory_off_admission_guard();
CREATE FUNCTION manual_inventory_off_series_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 IF NOT EXISTS(SELECT FROM manual_inventory_off_receipts WHERE(tenant_id,series_id)=(NEW.tenant_id,NEW.id)) THEN RAISE EXCEPTION 'Orphan manual series' USING ERRCODE='23514';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER manual_inventory_off_series_complete AFTER INSERT ON manual_inventory_off_series DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION manual_inventory_off_series_complete();

CREATE FUNCTION manual_inventory_off_apply(u uuid,k uuid,pid uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p public.manual_inventory_off_previews;a public.manual_inventory_off_admissions;r public.manual_inventory_off_receipts;s public.manual_inventory_off_series;
 f jsonb;rid uuid:=gen_random_uuid();sm uuid:=gen_random_uuid();bm uuid:=gen_random_uuid();effect jsonb;doc jsonb;pay jsonb;n bigint;d integer;nowat timestamptz;BEGIN
 PERFORM manual_inventory_off_require();
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Manual consent must be object' USING ERRCODE='23514';END IF;
 IF b<>jsonb_build_object('client_key',(b->>'client_key')::uuid,'scope_hash',b->>'scope_hash','confirmed',true) THEN RAISE EXCEPTION 'Explicit separate manual consent required' USING ERRCODE='23514';END IF;
 SELECT * INTO p FROM manual_inventory_off_previews WHERE(tenant_id,id)=(t,pid);IF p.id IS NULL THEN RAISE EXCEPTION 'Own manual preview missing' USING ERRCODE='P0002';END IF;
 PERFORM warehouse_inventory_policy_lock(t,(p.request->>'warehouse_id')::uuid);
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog.strict.quota:'||t,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('manual.off.quota:'||t,0));
 SELECT * INTO a FROM manual_inventory_off_admissions WHERE(tenant_id,client_key)=(t,(b->>'client_key')::uuid);
 IF a.id IS NOT NULL THEN IF(a.preview_id,a.actor_id,a.api_key_id,a.request) IS DISTINCT FROM(pid,u,k,b) THEN RAISE EXCEPTION 'Manual receipt key conflict' USING ERRCODE='23514';END IF;
 PERFORM manual_inventory_off_validate(a.id,false);RETURN jsonb_build_object('receipt',(SELECT payload FROM manual_inventory_off_receipts WHERE(tenant_id,id)=(t,a.id)),'reused',true);END IF;
 SELECT * INTO p FROM manual_inventory_off_previews WHERE(tenant_id,id)=(t,pid) FOR SHARE;
 IF p.id IS NULL THEN RAISE EXCEPTION 'Own manual preview missing' USING ERRCODE='P0002';END IF;
 IF(p.actor_id,p.api_key_id) IS DISTINCT FROM(u,k) OR p.scope_hash<>b->>'scope_hash' OR p.client_key=(b->>'client_key')::uuid
 OR EXISTS(SELECT FROM manual_inventory_off_receipts WHERE(tenant_id,preview_id)=(t,pid)) THEN RAISE EXCEPTION 'Preview custody/consent changed' USING ERRCODE='23514';END IF;
 nowat:=clock_timestamp();IF nowat>=p.expires_at OR extract(year FROM nowat)<>p.year THEN RAISE EXCEPTION 'Manual preview expired/year changed' USING ERRCODE='40001';END IF;
 f:=manual_inventory_off_frame((p.request->>'product_id')::uuid,(p.request->>'warehouse_id')::uuid,true);
 IF f<>p.frame OR manual_inventory_off_projection(f,p.request)<>p.projection THEN RAISE EXCEPTION 'Manual full source changed' USING ERRCODE='40001';END IF;
 INSERT INTO manual_inventory_off_admissions(id,tenant_id,preview_id,actor_id,api_key_id,client_key,request) VALUES(rid,t,pid,u,k,(b->>'client_key')::uuid,b);
 effect:=catalog_stock_control_effect_prepare(u,k,jsonb_build_object('source_kind','manual_off_correction','source_id',rid,'product_ids',jsonb_build_array(p.request->'product_id'),'warehouse_ids',jsonb_build_array(p.request->'warehouse_id')));
 IF effect IS NOT NULL THEN UPDATE manual_inventory_off_admissions SET strict_effect_id=(effect->>'id')::uuid WHERE id=rid;END IF;
 INSERT INTO manual_inventory_off_series(id,tenant_id,warehouse_id,kind,prefix) VALUES(gen_random_uuid(),t,(p.request->>'warehouse_id')::uuid,p.projection->>'kind',(p.projection->>'kind')||'-M') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;
 SELECT * INTO s FROM manual_inventory_off_series WHERE(tenant_id,warehouse_id,kind)=(t,(p.request->>'warehouse_id')::uuid,p.projection->>'kind') FOR SHARE;
 INSERT INTO manual_inventory_off_counters VALUES(t,s.id,p.year,1) ON CONFLICT(tenant_id,series_id,year) DO UPDATE SET value=manual_inventory_off_counters.value+1 RETURNING value INTO n;
 d:=(p.request->>'delta')::integer;
 UPDATE stock_locations SET quantity=quantity+d WHERE(tenant_id,warehouse_id,product_id,location)=(t,(p.request->>'warehouse_id')::uuid,(p.request->>'product_id')::uuid,p.request->>'location');
 INSERT INTO stock_location_movements(id,tenant_id,warehouse_id,product_id,location,delta,kind,operation_id,note) VALUES(bm,t,(p.request->>'warehouse_id')::uuid,(p.request->>'product_id')::uuid,p.request->>'location',d,'manual_off_correction',rid,p.request->>'note');
 UPDATE stock SET on_hand=on_hand+d WHERE(tenant_id,warehouse_id,product_id)=(t,(p.request->>'warehouse_id')::uuid,(p.request->>'product_id')::uuid);
 INSERT INTO stock_movements(id,tenant_id,warehouse_id,product_id,delta,kind,note) VALUES(sm,t,(p.request->>'warehouse_id')::uuid,(p.request->>'product_id')::uuid,d,'manual_off_correction',p.request->>'note');
 nowat:=clock_timestamp();doc:=jsonb_build_object('id',rid,'number',s.prefix||'/'||p.year||'/'||CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END,'kind',s.kind,'series_id',s.id,'year',p.year,'sequence',n::text,'warehouse_id',s.warehouse_id,
 'rows',jsonb_build_array(jsonb_build_object('ordinal',0,'product_id',p.request->'product_id','sku',f#>'{source,product,sku}','name',f#>'{source,product,name}','location',p.request->'location','delta',d,'quantity',abs(d))),'valuation',p.projection->'valuation');
 pay:=jsonb_build_object('id',rid,'preview_id',pid,'client_key',b->'client_key','protocol','manual_off_pw_rw_v1','request',p.request,'scope_hash',p.scope_hash,'source',p.frame->'source','projection',p.projection,'document',doc,'journals',jsonb_build_object('stock_movement_id',sm,'location_movement_id',bm),'created_at',to_char(nowat AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 INSERT INTO manual_inventory_off_receipts VALUES(rid,t,pid,(b->>'client_key')::uuid,s.id,p.year,n,sm,bm,pay,nowat);
 IF effect IS NOT NULL THEN PERFORM catalog_stock_control_effect_finish(u,k,(effect->>'id')::uuid,jsonb_build_object('manual_receipt_id',rid,'stock_movement_ids',jsonb_build_array(sm),'location_movement_ids',jsonb_build_array(bm),'layer_movement_ids','[]'::jsonb));END IF;
 PERFORM manual_inventory_off_validate(rid,true);
 INSERT INTO audit_events(id,tenant_id,user_id,action,entity_id,detail) VALUES(gen_random_uuid(),t,u,'inventory.manual_off.post',rid,'{}'::jsonb);
 RETURN jsonb_build_object('receipt',pay,'reused',false);END$$;

