AND h.version=1\n    AND h.method='FIFO' AND h.opening_operation_id=op.id AND h.currency=pv.request->>'currency' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))\n  THEN RAISE EXCEPTION 'Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF' USING ERRCODE='23514';END IF;\n  -- Every positive physical bin in the entire tenant, including nonstrict\n  -- catalogs, is represented once. Opening never writes stock or a second PZ.\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q\n    FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)\n  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;\n  IF countj<>0 THEN RAISE EXCEPTION 'Otwarcie nie obejmuje całego zapasu firmy' USING ERRCODE='23514';END IF;\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q,\n    r->>'lot_code' code,(r->>'unit_cost_minor')::bigint cost,r->>'currency' currency FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency\n    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)\n    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)\n    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin='opening'\n     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL\n     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))\n  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code\n    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;\n  IF countj<>0 OR jsonb_array_length(f->'positions')<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR jsonb_array_length(e.proof->'layer_movement_ids')<>jsonb_array_length(pv.snapshot->'rows')\n   OR EXISTS(SELECT FROM jsonb_array_elements(f->'layer_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'layer_movement_ids'))\n     AND(j->>'operation_id' IS DISTINCT FROM op.id::text OR j->>'kind'<>'opening' OR(j->>'delta')::integer<=0))\n  THEN RAISE EXCEPTION 'Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='inventory_import' THEN PERFORM public.catalog_stock_count_validate(eid);\n ELSIF a.source_kind='return' THEN PERFORM public.catalog_stock_return_validate(eid);\n ELSIF a.source_kind='dispatch' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego automatycznego WZ' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='stocktake' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego PW/RW' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='location_operation' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>'kind'='move') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->'bin_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'location_movement_ids')) AND j->>'operation_id' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->'stock')v WHERE coalesce((v->>'on_hand')::integer,0) IS DISTINCT FROM(SELECT(o->>'on_hand')::integer FROM jsonb_array_elements(a.before_frame->'stock')o WHERE(o->>'warehouse_id',o->>'product_id')=(v->>'warehouse_id',v->>'product_id'))) THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW; relokacja wymaga dowodu' USING ERRCODE='23514';END IF;\n ELSE RAISE EXCEPTION 'Źródło strict wymaga certyfikowanego adaptera dokumentu' USING ERRCODE='23514';END IF;END ","sha256":"aa3c54fdeee098fb147ae76b48d6197e03e16b162ff880ba0e1fd7c03847cace"},"catalog_stock_control_guards":{"body":" DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid='public.catalog_stock_control_guards()'::regprocedure);BEGIN\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace='public'::regnamespace AND p.proname IN('catalog_stock_control_xid_claim_guard','catalog_stock_control_capture_xid_birth'))<>13 OR\n  to_regprocedure('public.catalog_stock_control_owns_xmin(xid)') IS NULL OR\n  to_regprocedure('public.catalog_stock_control_prune_xid_claims()') IS NULL THEN RETURN false; END IF;\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'catalog_stock_control_%' AND relkind='r')<>14 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_control_%' AND c.relkind='r' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_control_%' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\n RETURN coalesce((SELECT fingerprint=public.catalog_stock_control_fingerprint() FROM public.catalog_stock_control_manifest WHERE id),false);END ","sha256":"71ae1c60ac7e99bc32e0175f59594d915dbfa6e9aef1a84bb0d349d36a5462b7"}}$manualold$::jsonb;
DO $$DECLARE n text;v jsonb;BEGIN FOR n,v IN SELECT key,value FROM jsonb_each((SELECT changed_functions FROM pg_temp.manual_inventory_off_install_basis)) LOOP
IF v->>'body' IS DISTINCT FROM(SELECT prosrc FROM pg_proc WHERE oid=('public.'||n||CASE n WHEN 'catalog_stock_control_effect_prepare' THEN '(uuid,uuid,jsonb)' WHEN 'catalog_stock_control_effect_validate' THEN '(uuid)' ELSE '()' END)::regprocedure) THEN RAISE EXCEPTION 'Changed152 predecessor' USING ERRCODE='55000';END IF;END LOOP;END$$;

CREATE FUNCTION manual_inventory_off_catalog_functions(original boolean) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_object_agg(p.proname||'('||oidvectortypes(p.proargtypes)||')',jsonb_build_object(
 'definition',CASE WHEN original AND p.proname IN('catalog_stock_control_effect_prepare','catalog_stock_control_effect_validate','catalog_stock_control_guards') THEN replace(pg_get_functiondef(p.oid),(SELECT payload#>>ARRAY['successor_functions',p.proname,'body'] FROM manual_inventory_off_certificate WHERE id),(SELECT payload#>>ARRAY['predecessor_functions',p.proname,'body'] FROM manual_inventory_off_certificate WHERE id)) ELSE pg_get_functiondef(p.oid) END,
 'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'volatile',p.provolatile,'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'cost',p.procost,'rows',p.prorows,
 'result',pg_get_function_result(p.oid),'args',pg_get_function_identity_arguments(p.oid),
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x)) ORDER BY p.proname,oidvectortypes(p.proargtypes))
 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND starts_with(p.proname,'catalog_stock_control_')
$$;
ALTER TABLE pg_temp.manual_inventory_off_install_basis ADD COLUMN catalog_functions jsonb;
UPDATE pg_temp.manual_inventory_off_install_basis SET catalog_functions=manual_inventory_off_catalog_functions(false);

-- Only four definitions are projected; all current properties/ACL remain native.
CREATE FUNCTION manual_inventory_off_projected_definition(fn oid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT CASE WHEN p.pronamespace='public'::regnamespace AND p.proname IN('catalog_stock_control_effect_prepare','catalog_stock_control_effect_validate','catalog_stock_control_guards','b2b_credit_fingerprint') THEN
 replace(pg_get_functiondef(p.oid),p.prosrc,(SELECT payload#>>ARRAY['predecessor_functions',p.proname,'body'] FROM public.manual_inventory_off_certificate WHERE id))
 ELSE pg_get_functiondef(p.oid) END FROM pg_proc p WHERE p.oid=fn
$$;
CREATE FUNCTION manual_inventory_off_projected_functions(original boolean) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_object_agg(p.proname,jsonb_build_object(
 'definition',CASE WHEN original THEN manual_inventory_off_projected_definition(p.oid) ELSE pg_get_functiondef(p.oid) END,
 'owner',pg_get_userbyid(p.proowner),'sd',p.prosecdef,'config',p.proconfig,'volatile',p.provolatile,'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'kind',p.prokind,'retset',p.proretset,'cost',p.procost,'rows',p.prorows,
 'result',pg_get_function_result(p.oid),'args',pg_get_function_identity_arguments(p.oid),'argmodes',p.proargmodes,'argnames',p.proargnames,'defaults',pg_get_expr(p.proargdefaults,0),'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x)) ORDER BY p.proname)
 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.oid=ANY(ARRAY['public.catalog_stock_control_effect_prepare(uuid,uuid,jsonb)','public.catalog_stock_control_effect_validate(uuid)','public.catalog_stock_control_guards()','public.b2b_credit_fingerprint()']::regprocedure[])
$$;
UPDATE pg_temp.manual_inventory_off_install_basis SET projected_functions=manual_inventory_off_projected_functions(false),
 changed_functions=changed_functions||jsonb_build_object('b2b_credit_fingerprint',(SELECT jsonb_build_object('body',prosrc,'sha256',encode(sha256(convert_to(prosrc,'UTF8')),'hex')) FROM pg_proc WHERE oid='public.b2b_credit_fingerprint()'::regprocedure));

CREATE OR REPLACE FUNCTION catalog_stock_control_effect_prepare(uid uuid,kid uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;strictids jsonb;eid uuid:=gen_random_uuid();s public.catalog_stock_control_series;d public.warehouse_documents;w uuid;kindj text;yr integer:=extract(year FROM transaction_timestamp());n bigint;num jsonb;f jsonb;old public.catalog_stock_control_effect_admissions;pv public.wms_previews;
BEGIN PERFORM public.catalog_stock_control_require();
 -- No public activation scopes are imposed on ordinary physical callers; their
 -- actual enclosing source IAM is enlisted by the trusted server adapter.
 IF uid IS NOT NULL AND NOT EXISTS(SELECT FROM public.memberships WHERE(tenant_id,user_id)=(t,uid) AND role IN('admin','operator')) THEN RAISE EXCEPTION 'Brak aktualnego operatora fizycznego efektu' USING ERRCODE='42501';END IF;
 IF b->>'source_kind' NOT IN('warehouse_document','purchase_receipt','dispatch','stocktake','location_operation','wms_movement','wms_receipt','return','wms_opening','catalog_import','inventory_import','manual_off_correction') THEN RAISE EXCEPTION 'Nieznane źródło fizyczne' USING ERRCODE='23514';END IF;

 IF b->>'source_kind'='manual_off_correction' AND NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma JOIN public.manual_inventory_off_previews mp ON(mp.tenant_id,mp.id)=(ma.tenant_id,ma.preview_id)
 WHERE(ma.tenant_id,ma.id,ma.actor_id)=(t,(b->>'source_id')::uuid,uid) AND ma.api_key_id IS NOT DISTINCT FROM kid AND ma.root_xid=pg_current_xact_id()
 AND b=jsonb_build_object('source_kind','manual_off_correction','source_id',ma.id,'product_ids',jsonb_build_array(mp.request->'product_id'),'warehouse_ids',jsonb_build_array(mp.request->'warehouse_id')))
 THEN RAISE EXCEPTION 'Manual strict source requires genuine managed parent' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog.strict.lifecycle:'||t,0));
 SELECT coalesce(jsonb_agg(DISTINCT p.catalog_id ORDER BY p.catalog_id),'[]') INTO strictids FROM public.products p JOIN public.catalog_stock_control_policies h ON(h.tenant_id,h.catalog_id)=(p.tenant_id,p.catalog_id) WHERE p.tenant_id=t AND p.id IN(SELECT v::uuid FROM jsonb_array_elements_text(b->'product_ids')v);
 IF jsonb_array_length(strictids)=0 THEN RETURN NULL;END IF;
 FOR w IN SELECT v::uuid FROM jsonb_array_elements_text(b->'warehouse_ids')v ORDER BY v LOOP PERFORM public.warehouse_inventory_policy_lock(t,w);END LOOP;
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog.strict.quota:'||t,0));
 SELECT * INTO old FROM public.catalog_stock_control_effect_admissions WHERE(tenant_id,source_kind,source_id)=(t,b->>'source_kind',(b->>'source_id')::uuid);
 IF old.id IS NOT NULL THEN IF old.sealed THEN RETURN NULL;END IF;IF old.txid<>pg_current_xact_id() OR old.actor_id IS DISTINCT FROM uid OR old.api_key_id IS DISTINCT FROM kid OR old.request<>b THEN RAISE EXCEPTION 'Inne przyjęcie fizycznego źródła' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('id',old.id,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',old.number);END IF;
 IF b->>'source_kind'='warehouse_document' THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(t,(b->>'source_id')::uuid);IF d.id IS NULL OR d.status<>'draft' THEN RAISE EXCEPTION 'Historyczne źródło nie otrzyma nowego numeru' USING ERRCODE='23514';END IF;kindj:=CASE d.kind WHEN 'receipt' THEN 'PZ' WHEN 'transfer' THEN 'MM' WHEN 'issue' THEN 'WZ' END;IF kindj IS NULL THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW' USING ERRCODE='23514';END IF;
 INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,d.warehouse_id,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;
 SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,d.warehouse_id,kindj) FOR UPDATE;
 n:=public.catalog_stock_control_next(t,s.id,yr);
 num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;
 IF b->>'source_kind' IN('purchase_receipt','wms_receipt') THEN SELECT v::uuid INTO w FROM jsonb_array_elements_text(b->'warehouse_ids')v;IF jsonb_array_length(b->'warehouse_ids')<>1 THEN RAISE EXCEPTION 'Przyjęcie dostawy ma jeden rzeczywisty magazyn' USING ERRCODE='23514';END IF;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,'PZ','PZ','PZ') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,'PZ') FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind','PZ','number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;
 IF b->>'source_kind'='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);IF pv.id IS NULL OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.kind NOT IN('issue','transfer','bin_move','adjustment') OR b->'product_ids'<>jsonb_build_array(pv.request->'product_id') OR b->'warehouse_ids'<>(SELECT jsonb_agg(v ORDER BY v#>>'{}') FROM jsonb_array_elements(jsonb_build_array(pv.request->'warehouse_id')||CASE WHEN pv.kind='transfer' THEN jsonb_build_array(pv.request->'destination_warehouse_id') ELSE '[]'::jsonb END)v) THEN RAISE EXCEPTION 'Brak własnego gotowego źródła ruchu WMS lub strict PW/RW' USING ERRCODE='23514';END IF;kindj:=CASE pv.kind WHEN 'issue' THEN 'WZ' WHEN 'transfer' THEN 'MM' WHEN 'adjustment' THEN CASE WHEN (pv.request->>'quantity')::integer>0 THEN 'PW' ELSE 'RW' END END;IF kindj IS NOT NULL THEN w:=(pv.request->>'warehouse_id')::uuid;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,kindj) FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;END IF;
 IF b->>'source_kind'='wms_opening' AND EXISTS(SELECT FROM public.wms_operations o JOIN public.wms_policies h
  ON(h.tenant_id,h.opening_operation_id)=(o.tenant_id,o.id) WHERE o.tenant_id=t AND o.kind='opening'
  AND o.request->>'preview_id'=b->>'source_id') THEN RETURN NULL;END IF;
 IF b->>'source_kind'='wms_opening' THEN
  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);
  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.policy_version<>0
   OR b->'product_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'product_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)
   OR b->'warehouse_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'warehouse_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)
   OR EXISTS(SELECT FROM public.wms_policies WHERE tenant_id=t)
   OR EXISTS(SELECT FROM public.wms_lots WHERE tenant_id=t)
   OR EXISTS(SELECT FROM public.wms_cost_layers WHERE tenant_id=t)
   OR EXISTS(SELECT FROM public.wms_layer_positions WHERE tenant_id=t)
  THEN RAISE EXCEPTION 'Otwarcie strict wymaga własnego pełnego źródła WMS OFF' USING ERRCODE='23514';END IF;
 END IF;
 f:=public.catalog_stock_control_effect_frame(b);
 INSERT INTO public.catalog_stock_control_effect_admissions(id,tenant_id,actor_id,api_key_id,source_kind,source_id,request,before_frame,number) VALUES(eid,t,uid,kid,b->>'source_kind',(b->>'source_id')::uuid,b,f,num);
 RETURN jsonb_build_object('id',eid,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',num);END $$;
CREATE OR REPLACE FUNCTION catalog_stock_control_effect_validate(eid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE a public.catalog_stock_control_effect_admissions;e public.catalog_stock_control_effects;f jsonb;kindj text;keyj text;ids jsonb;news jsonb;beforej jsonb;afterj jsonb;x jsonb;priorj jsonb;delta numeric;sumdelta numeric;d public.warehouse_documents;op public.wms_operations;pv public.wms_previews;countj bigint;
BEGIN SELECT * INTO a FROM public.catalog_stock_control_effect_admissions WHERE id=eid;IF a.id IS NULL OR a.txid<>pg_current_xact_id() THEN RAISE EXCEPTION 'Brak przyjęcia strict w bieżącej transakcji' USING ERRCODE='23514';END IF;SELECT * INTO e FROM public.catalog_stock_control_effects WHERE(tenant_id,admission_id)=(a.tenant_id,a.id);IF e.admission_id IS NULL THEN RAISE EXCEPTION 'Brak pełnego dokumentu fizycznego efektu' USING ERRCODE='23514';END IF;
 f:=public.catalog_stock_control_effect_frame(a.request);IF NOT EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions later WHERE later.tenant_id=a.tenant_id AND later.txid=a.txid AND later.id<>a.id AND later.sealed AND later.request->'product_ids'=a.request->'product_ids' AND later.request->'warehouse_ids'=a.request->'warehouse_ids' AND later.before_frame=e.after_frame) AND f<>e.after_frame THEN RAISE EXCEPTION 'Zapieczętowany fizyczny efekt zmienił się' USING ERRCODE='23514';END IF;f:=e.after_frame;
 FOREACH kindj IN ARRAY ARRAY['stock','bin','layer'] LOOP keyj:=CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bin' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END;
 ids:=coalesce(e.proof->keyj,'[]');beforej:=a.before_frame->(kindj||'_journals');afterj:=f->(kindj||'_journals');
 IF EXISTS(SELECT FROM jsonb_array_elements(beforej)b WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(afterj)n WHERE n=b)) THEN RAISE EXCEPTION 'Historia fizyczna została zmieniona' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(v->'id' ORDER BY v->>'id'),'[]') INTO news FROM jsonb_array_elements(afterj)v WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(beforej)o WHERE o->>'id'=v->>'id');
 IF news<>(SELECT coalesce(jsonb_agg(v ORDER BY v#>>'{}'),'[]') FROM jsonb_array_elements(ids)v) OR jsonb_array_length(ids)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(ids)v) THEN RAISE EXCEPTION 'Dowód nie obejmuje wszystkich rzeczywistych ruchów' USING ERRCODE='23514';END IF;END LOOP;
 -- Every signed cell delta equals the actual new journal sum, including net-zero SKU moves.
 FOREACH kindj IN ARRAY ARRAY['stock','bins','positions'] LOOP
 WITH old_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(a.before_frame->kindj)v),
 new_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(f->kindj)v),
 journals AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,sum((v->>'delta')::numeric) delta FROM jsonb_array_elements(f->(CASE kindj WHEN 'stock' THEN 'stock_journals' WHEN 'bins' THEN 'bin_journals' ELSE 'layer_journals' END))v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->(CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bins' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END))) GROUP BY 1,2,3,4),
 cells AS(SELECT coalesce(n.w,o.w) w,coalesce(n.p,o.p) p,coalesce(n.l,o.l) l,coalesce(n.layer,o.layer) layer,coalesce(n.q,0)-coalesce(o.q,0) delta FROM old_cells o FULL JOIN new_cells n USING(w,p,l,layer))
 SELECT count(*) INTO countj FROM cells c FULL JOIN journals j USING(w,p,l,layer) WHERE coalesce(c.delta,0)<>coalesce(j.delta,0);
 IF countj<>0 THEN RAISE EXCEPTION 'Ruch nie odpowiada dokładnemu stanowi komórki' USING ERRCODE='23514';END IF;END LOOP;
 IF a.source_kind IN('warehouse_document','purchase_receipt','wms_movement','wms_receipt') THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(a.tenant_id,(e.proof->>'warehouse_document_id')::uuid);IF d.id IS NULL OR d.status<>'posted' OR(a.source_kind='warehouse_document' AND d.id<>a.source_id) OR(a.number IS NOT NULL AND d.number<>a.number->>'number' AND NOT(a.source_kind='wms_movement' AND EXISTS(SELECT FROM public.wms_previews wp WHERE(wp.tenant_id,wp.id)=(a.tenant_id,a.source_id) AND wp.kind='adjustment'))) THEN RAISE EXCEPTION 'Brak rzeczywistego zaksięgowanego dokumentu' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(f->'stock_journals')v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'stock_movement_ids')) AND v->>'warehouse_document_id' IS DISTINCT FROM d.id::text) THEN RAISE EXCEPTION 'Ruch obcego dokumentu' USING ERRCODE='23514';END IF;
 IF a.source_kind='purchase_receipt' AND NOT EXISTS(SELECT FROM public.purchase_receipts pr JOIN public.purchase_orders po ON(po.tenant_id,po.id)=(pr.tenant_id,pr.order_id) WHERE(pr.tenant_id,pr.id,pr.document_id)=(a.tenant_id,a.source_id,d.id) AND pr.id=e.purchase_receipt_id AND po.warehouse_id=d.warehouse_id AND NOT EXISTS(SELECT FROM public.purchase_receipt_lines l WHERE(l.tenant_id,l.receipt_id)=(pr.tenant_id,pr.id) AND NOT EXISTS(SELECT FROM public.warehouse_document_lines dl WHERE(dl.tenant_id,dl.document_id,dl.product_id,dl.quantity,dl.location)=(l.tenant_id,d.id,l.product_id,l.quantity,l.location)))) THEN RAISE EXCEPTION 'Dowód PZ nie odpowiada rzeczywistemu przyjęciu dostawy' USING ERRCODE='23514';END IF;
 IF a.source_kind IN('wms_movement','wms_receipt') THEN SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);IF op.id IS NULL OR op.warehouse_document_id IS DISTINCT FROM d.id OR(a.source_kind='wms_receipt' AND(op.kind<>'receipt' OR op.client_key<>a.source_id OR op.purchase_receipt_id IS NOT NULL)) OR(a.source_kind='wms_movement' AND op.request->>'preview_id' IS DISTINCT FROM a.source_id::text) THEN RAISE EXCEPTION 'Dokument nie odpowiada rzeczywistemu źródłu WMS' USING ERRCODE='23514';END IF;IF a.source_kind='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id)=(a.tenant_id,a.source_id);IF pv.id IS NULL OR pv.kind<>op.kind OR d.reference<>'WMS/'||pv.id OR d.warehouse_id<>(pv.request->>'warehouse_id')::uuid THEN RAISE EXCEPTION 'Obcy zapisany plan ruchu WMS' USING ERRCODE='23514';END IF;IF pv.kind='adjustment' AND e.proof->'correction_document' IS DISTINCT FROM public.catalog_stock_control_wms_correction_build(a.id,e.proof) THEN RAISE EXCEPTION 'Niepełny zapisany dokument PW/RW korekty' USING ERRCODE='23514';END IF;END IF;END IF;
 ELSIF a.source_kind='wms_opening' THEN
  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(a.tenant_id,a.source_id,a.actor_id);
  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);
  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.policy_version<>0 OR op.id IS NULL
   OR op.kind<>'opening' OR op.actor_id IS DISTINCT FROM a.actor_id OR op.policy_version<>1
   OR op.request->>'preview_id' IS DISTINCT FROM pv.id::text OR op.request->>'scope_hash' IS DISTINCT FROM pv.scope_hash
   OR op.request->'confirmed' IS DISTINCT FROM 'true'::jsonb
   OR (pv.snapshot->'valuation'->>'unknown_quantity'<>'0' AND op.request->'ack_unknown_costs' IS DISTINCT FROM 'true'::jsonb)
   OR NOT EXISTS(SELECT FROM public.wms_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,op.id) AND public.catalog_stock_control_owns_xmin(o.xmin))
   OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL OR op.order_id IS NOT NULL OR op.return_id IS NOT NULL
   OR e.warehouse_document_id IS NOT NULL OR e.location_operation_id IS NOT NULL OR a.number IS NOT NULL
   OR a.before_frame->'stock'<>f->'stock' OR a.before_frame->'bins'<>f->'bins'
   OR a.before_frame->'positions'<>'[]'::jsonb
   OR e.proof->'stock_movement_ids'<>'[]'::jsonb OR e.proof->'location_movement_ids'<>'[]'::jsonb
   OR NOT EXISTS(SELECT FROM public.wms_policies h WHERE h.tenant_id=a.tenant_id AND h.enabled AND h.version=1
    AND h.method='FIFO' AND h.opening_operation_id=op.id AND h.currency=pv.request->>'currency' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))
  THEN RAISE EXCEPTION 'Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF' USING ERRCODE='23514';END IF;
  -- Every positive physical bin in the entire tenant, including nonstrict
  -- catalogs, is represented once. Opening never writes stock or a second PZ.
  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q
    FROM jsonb_array_elements(pv.snapshot->'rows')r),
   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)
  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;
  IF countj<>0 THEN RAISE EXCEPTION 'Otwarcie nie obejmuje całego zapasu firmy' USING ERRCODE='23514';END IF;
  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q,
    r->>'lot_code' code,(r->>'unit_cost_minor')::bigint cost,r->>'currency' currency FROM jsonb_array_elements(pv.snapshot->'rows')r),
   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency
    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)
    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)
    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin='opening'
     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL
     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))
  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code
    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;
  IF countj<>0 OR jsonb_array_length(f->'positions')<>jsonb_array_length(pv.snapshot->'rows')
   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')
   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')
   OR jsonb_array_length(e.proof->'layer_movement_ids')<>jsonb_array_length(pv.snapshot->'rows')
   OR EXISTS(SELECT FROM jsonb_array_elements(f->'layer_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'layer_movement_ids'))
     AND(j->>'operation_id' IS DISTINCT FROM op.id::text OR j->>'kind'<>'opening' OR(j->>'delta')::integer<=0))
  THEN RAISE EXCEPTION 'Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła' USING ERRCODE='23514';END IF;
 ELSIF a.source_kind='inventory_import' THEN PERFORM public.catalog_stock_count_validate(eid);
 ELSIF a.source_kind='return' THEN PERFORM public.catalog_stock_return_validate(eid);
 ELSIF a.source_kind='dispatch' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego automatycznego WZ' USING ERRCODE='23514';END IF;
 ELSIF a.source_kind='stocktake' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego PW/RW' USING ERRCODE='23514';END IF;
 ELSIF a.source_kind='location_operation' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>'kind'='move') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->'bin_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'location_movement_ids')) AND j->>'operation_id' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->'stock')v WHERE coalesce((v->>'on_hand')::integer,0) IS DISTINCT FROM(SELECT(o->>'on_hand')::integer FROM jsonb_array_elements(a.before_frame->'stock')o WHERE(o->>'warehouse_id',o->>'product_id')=(v->>'warehouse_id',v->>'product_id'))) THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW; relokacja wymaga dowodu' USING ERRCODE='23514';END IF;

 ELSIF a.source_kind='manual_off_correction' THEN
 IF e.proof<>jsonb_build_object('manual_receipt_id',a.source_id,'stock_movement_ids',jsonb_build_array((SELECT stock_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),
 'location_movement_ids',jsonb_build_array((SELECT location_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),'layer_movement_ids','[]'::jsonb)
 OR a.number IS NOT NULL OR e.warehouse_document_id IS NOT NULL OR e.operation_id IS NOT NULL OR e.purchase_receipt_id IS NOT NULL OR e.dispatch_receipt_id IS NOT NULL OR e.adjustment_receipt_id IS NOT NULL OR e.location_operation_id IS NOT NULL
 OR NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma WHERE(ma.tenant_id,ma.id,ma.strict_effect_id,ma.actor_id)=(a.tenant_id,a.source_id,a.id,a.actor_id) AND ma.api_key_id IS NOT DISTINCT FROM a.api_key_id AND ma.root_xid=a.txid)
 THEN RAISE EXCEPTION 'Manual strict proof does not bind genuine parent' USING ERRCODE='23514';END IF;
 -- Parent validation excludes the strict-sealed predicate until effect_finish seals.
 PERFORM public.manual_inventory_off_validate(a.source_id,false);
 ELSE RAISE EXCEPTION 'Źródło strict wymaga certyfikowanego adaptera dokumentu' USING ERRCODE='23514';END IF;END $$;
CREATE OR REPLACE FUNCTION catalog_stock_control_guards() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid='public.catalog_stock_control_guards()'::regprocedure);BEGIN
 IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace='public'::regnamespace AND p.proname IN('catalog_stock_control_xid_claim_guard','catalog_stock_control_capture_xid_birth'))<>13 OR
  to_regprocedure('public.catalog_stock_control_owns_xmin(xid)') IS NULL OR
  to_regprocedure('public.catalog_stock_control_prune_xid_claims()') IS NULL THEN RETURN false; END IF;
 IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'catalog_stock_control_%' AND relkind='r')<>14 THEN RETURN false;END IF;
 IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_control_%' AND c.relkind='r' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_control_%' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;
 RETURN public.manual_inventory_off_valid();END $$;
CREATE FUNCTION manual_inventory_off_original152_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT public.catalog_stock_control_hash(jsonb_build_object('count_module',public.catalog_stock_count_fingerprint(),'return_module',public.catalog_stock_return_fingerprint(),'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable) ORDER BY CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl_grant),'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable) ORDER BY CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable),'[]'::jsonb) FROM aclexplode(a.attacl) acl_grant)) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(k.oid,true) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),'indexes',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=c.oid),'policies',(SELECT jsonb_agg(jsonb_build_object('name',p.polname,'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles)r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_control_%' AND c.relkind='r'),'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'args',oidvectortypes(p.proargtypes),'body',CASE WHEN p.proname IN('catalog_stock_control_effect_prepare','catalog_stock_control_effect_validate','catalog_stock_control_guards') THEN (SELECT payload#>>ARRAY['predecessor_functions',p.proname,'body'] FROM public.manual_inventory_off_certificate WHERE id) ELSE p.prosrc END,'owner',pg_get_userbyid(p.proowner),'sd',p.prosecdef,'config',p.proconfig,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable) ORDER BY CASE WHEN acl_grant.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(acl_grant.grantee) END,pg_get_userbyid(acl_grant.grantor),acl_grant.privilege_type,acl_grant.is_grantable),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl_grant)) ORDER BY p.proname,oidvectortypes(p.proargtypes)) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_control_%'),'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'type',t.tgtype,'enabled',t.tgenabled,'def',pg_get_triggerdef(t.oid,true)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.proname LIKE 'catalog_stock_control_%'))) $$;
CREATE FUNCTION manual_inventory_off_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND starts_with(c.relname,'manual_inventory_off_') AND c.relkind IN('r','p')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(a.attacl) x),'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',(SELECT collname FROM pg_collation WHERE oid=a.attcollation)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE c.relnamespace='public'::regnamespace AND starts_with(c.relname,'manual_inventory_off_') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',c.conname,'def',pg_get_constraintdef(c.oid,true),'validated',c.convalidated) ORDER BY t.relname,c.conname) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid WHERE t.relnamespace='public'::regnamespace AND starts_with(t.relname,'manual_inventory_off_')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',idx.relname,'def',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) ORDER BY t.relname,idx.relname) FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid JOIN pg_class idx ON idx.oid=i.indexrelid WHERE t.relnamespace='public'::regnamespace AND starts_with(t.relname,'manual_inventory_off_')),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'def',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(starts_with(t.tgname,'manual_inventory_off_') OR(c.relnamespace='public'::regnamespace AND starts_with(c.relname,'manual_inventory_off_')))),
 'policies',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY c.relname,p.polname) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace='public'::regnamespace AND starts_with(c.relname,'manual_inventory_off_')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'def',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x),'app_execute',has_function_privilege('dyna_app',p.oid,'EXECUTE')) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND starts_with(p.proname,'manual_inventory_off_')),
 'app_role',(SELECT jsonb_build_object('superuser',r.rolsuper,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'create_role',r.rolcreaterole,'create_db',r.rolcreatedb,'login',r.rolcanlogin) FROM pg_roles r WHERE rolname='dyna_app'),
 'app_acl',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'select',has_table_privilege('dyna_app',c.oid,'SELECT'),'insert',has_table_privilege('dyna_app',c.oid,'INSERT'),'update',has_table_privilege('dyna_app',c.oid,'UPDATE'),'delete',has_table_privilege('dyna_app',c.oid,'DELETE')) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND starts_with(c.relname,'manual_inventory_off_') AND c.relkind IN('r','p'))
 )::text,'UTF8')),'hex')
$$;

CREATE FUNCTION manual_inventory_off_certificate_seal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE b record;BEGIN
 IF current_user<>session_user OR to_regclass('pg_temp.manual_inventory_off_install_basis') IS NULL THEN RAISE EXCEPTION 'Private169 seal context missing' USING ERRCODE='42501';END IF;
 SELECT * INTO b FROM pg_temp.manual_inventory_off_install_basis;
 IF b.owner_name<>current_user OR b.root_xid<>pg_current_xact_id()::text OR b.start_at<>transaction_timestamp() OR b.backend_pid<>pg_backend_pid()
 OR NEW.payload->'original152_manifest' IS DISTINCT FROM b.original152_manifest OR NEW.payload->'predecessor_functions' IS DISTINCT FROM b.changed_functions
 OR NEW.payload->'predecessor_catalog_functions' IS DISTINCT FROM b.catalog_functions
 OR NEW.payload->'projected_functions' IS DISTINCT FROM b.projected_functions
 OR NEW.payload->>'original160_fingerprint' IS DISTINCT FROM b.original160_fingerprint
 OR NEW.payload->>'predecessor_fingerprint' IS DISTINCT FROM b.predecessor_fingerprint
 OR NEW.payload->>'successor_fingerprint' IS DISTINCT FROM catalog_stock_control_fingerprint()
 OR NEW.payload->>'own_fingerprint' IS DISTINCT FROM manual_inventory_off_fingerprint() THEN RAISE EXCEPTION 'Private169 seal differs from genuine owner basis' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER manual_inventory_off_certificate_seal BEFORE INSERT ON manual_inventory_off_certificate FOR EACH ROW EXECUTE FUNCTION manual_inventory_off_certificate_seal();

CREATE FUNCTION manual_inventory_off_projection_valid() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE cert jsonb;n text;actual text;BEGIN
 IF to_regclass('public.manual_inventory_off_certificate') IS NULL OR(SELECT count(*) FROM manual_inventory_off_certificate)<>1 THEN RETURN false;END IF;
 SELECT payload INTO cert FROM manual_inventory_off_certificate WHERE id;
 IF jsonb_typeof(cert) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF jsonb_typeof(cert->'projected_functions') IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF cert->>'profile' IS DISTINCT FROM '152-original-manual-off-pw-rw/v1'
 OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(cert) AS cert_keys(key)) IS DISTINCT FROM ARRAY['original152_manifest','original160_fingerprint','own_fingerprint','predecessor_catalog_functions','predecessor_fingerprint','predecessor_functions','profile','projected_functions','successor_fingerprint','successor_functions']::text[]
 OR cert->'predecessor_functions' IS DISTINCT FROM $projectionold${"catalog_stock_control_effect_prepare":{"body":"\nDECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;strictids jsonb;eid uuid:=gen_random_uuid();s public.catalog_stock_control_series;d public.warehouse_documents;w uuid;kindj text;yr integer:=extract(year FROM transaction_timestamp());n bigint;num jsonb;f jsonb;old public.catalog_stock_control_effect_admissions;pv public.wms_previews;\nBEGIN PERFORM public.catalog_stock_control_require();\n -- No public activation scopes are imposed on ordinary physical callers; their\n -- actual enclosing source IAM is enlisted by the trusted server adapter.\n IF uid IS NOT NULL AND NOT EXISTS(SELECT FROM public.memberships WHERE(tenant_id,user_id)=(t,uid) AND role IN('admin','operator')) THEN RAISE EXCEPTION 'Brak aktualnego operatora fizycznego efektu' USING ERRCODE='42501';END IF;\n IF b->>'source_kind' NOT IN('warehouse_document','purchase_receipt','dispatch','stocktake','location_operation','wms_movement','wms_receipt','return','wms_opening','catalog_import','inventory_import') THEN RAISE EXCEPTION 'Nieznane źródło fizyczne' USING ERRCODE='23514';END IF;\n PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog.strict.lifecycle:'||t,0));\n SELECT coalesce(jsonb_agg(DISTINCT p.catalog_id ORDER BY p.catalog_id),'[]') INTO strictids FROM public.products p JOIN public.catalog_stock_control_policies h ON(h.tenant_id,h.catalog_id)=(p.tenant_id,p.catalog_id) WHERE p.tenant_id=t AND p.id IN(SELECT v::uuid FROM jsonb_array_elements_text(b->'product_ids')v);\n IF jsonb_array_length(strictids)=0 THEN RETURN NULL;END IF;\n FOR w IN SELECT v::uuid FROM jsonb_array_elements_text(b->'warehouse_ids')v ORDER BY v LOOP PERFORM public.warehouse_inventory_policy_lock(t,w);END LOOP;\n PERFORM pg_advisory_xact_lock(hashtextextended('catalog.strict.quota:'||t,0));\n SELECT * INTO old FROM public.catalog_stock_control_effect_admissions WHERE(tenant_id,source_kind,source_id)=(t,b->>'source_kind',(b->>'source_id')::uuid);\n IF old.id IS NOT NULL THEN IF old.sealed THEN RETURN NULL;END IF;IF old.txid<>pg_current_xact_id() OR old.actor_id IS DISTINCT FROM uid OR old.api_key_id IS DISTINCT FROM kid OR old.request<>b THEN RAISE EXCEPTION 'Inne przyjęcie fizycznego źródła' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('id',old.id,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',old.number);END IF;\n IF b->>'source_kind'='warehouse_document' THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(t,(b->>'source_id')::uuid);IF d.id IS NULL OR d.status<>'draft' THEN RAISE EXCEPTION 'Historyczne źródło nie otrzyma nowego numeru' USING ERRCODE='23514';END IF;kindj:=CASE d.kind WHEN 'receipt' THEN 'PZ' WHEN 'transfer' THEN 'MM' WHEN 'issue' THEN 'WZ' END;IF kindj IS NULL THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW' USING ERRCODE='23514';END IF;\n INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,d.warehouse_id,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;\n SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,d.warehouse_id,kindj) FOR UPDATE;\n n:=public.catalog_stock_control_next(t,s.id,yr);\n num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;\n IF b->>'source_kind' IN('purchase_receipt','wms_receipt') THEN SELECT v::uuid INTO w FROM jsonb_array_elements_text(b->'warehouse_ids')v;IF jsonb_array_length(b->'warehouse_ids')<>1 THEN RAISE EXCEPTION 'Przyjęcie dostawy ma jeden rzeczywisty magazyn' USING ERRCODE='23514';END IF;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,'PZ','PZ','PZ') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,'PZ') FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind','PZ','number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;\n IF b->>'source_kind'='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);IF pv.id IS NULL OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.kind NOT IN('issue','transfer','bin_move','adjustment') OR b->'product_ids'<>jsonb_build_array(pv.request->'product_id') OR b->'warehouse_ids'<>(SELECT jsonb_agg(v ORDER BY v#>>'{}') FROM jsonb_array_elements(jsonb_build_array(pv.request->'warehouse_id')||CASE WHEN pv.kind='transfer' THEN jsonb_build_array(pv.request->'destination_warehouse_id') ELSE '[]'::jsonb END)v) THEN RAISE EXCEPTION 'Brak własnego gotowego źródła ruchu WMS lub strict PW/RW' USING ERRCODE='23514';END IF;kindj:=CASE pv.kind WHEN 'issue' THEN 'WZ' WHEN 'transfer' THEN 'MM' WHEN 'adjustment' THEN CASE WHEN (pv.request->>'quantity')::integer>0 THEN 'PW' ELSE 'RW' END END;IF kindj IS NOT NULL THEN w:=(pv.request->>'warehouse_id')::uuid;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,kindj) FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;END IF;\n IF b->>'source_kind'='wms_opening' AND EXISTS(SELECT FROM public.wms_operations o JOIN public.wms_policies h\n  ON(h.tenant_id,h.opening_operation_id)=(o.tenant_id,o.id) WHERE o.tenant_id=t AND o.kind='opening'\n  AND o.request->>'preview_id'=b->>'source_id') THEN RETURN NULL;END IF;\n IF b->>'source_kind'='wms_opening' THEN\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);\n  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.policy_version<>0\n   OR b->'product_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'product_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)\n   OR b->'warehouse_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'warehouse_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)\n   OR EXISTS(SELECT FROM public.wms_policies WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_lots WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_cost_layers WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_layer_positions WHERE tenant_id=t)\n  THEN RAISE EXCEPTION 'Otwarcie strict wymaga własnego pełnego źródła WMS OFF' USING ERRCODE='23514';END IF;\n END IF;\n f:=public.catalog_stock_control_effect_frame(b);\n INSERT INTO public.catalog_stock_control_effect_admissions(id,tenant_id,actor_id,api_key_id,source_kind,source_id,request,before_frame,number) VALUES(eid,t,uid,kid,b->>'source_kind',(b->>'source_id')::uuid,b,f,num);\n RETURN jsonb_build_object('id',eid,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',num);END ","sha256":"8124f34c7893ddf592740b55738b7b48eb67ac1694add340bbe29c0385366044"},"catalog_stock_control_effect_validate":{"body":"\nDECLARE a public.catalog_stock_control_effect_admissions;e public.catalog_stock_control_effects;f jsonb;kindj text;keyj text;ids jsonb;news jsonb;beforej jsonb;afterj jsonb;x jsonb;priorj jsonb;delta numeric;sumdelta numeric;d public.warehouse_documents;op public.wms_operations;pv public.wms_previews;countj bigint;\nBEGIN SELECT * INTO a FROM public.catalog_stock_control_effect_admissions WHERE id=eid;IF a.id IS NULL OR a.txid<>pg_current_xact_id() THEN RAISE EXCEPTION 'Brak przyjęcia strict w bieżącej transakcji' USING ERRCODE='23514';END IF;SELECT * INTO e FROM public.catalog_stock_control_effects WHERE(tenant_id,admission_id)=(a.tenant_id,a.id);IF e.admission_id IS NULL THEN RAISE EXCEPTION 'Brak pełnego dokumentu fizycznego efektu' USING ERRCODE='23514';END IF;\n f:=public.catalog_stock_control_effect_frame(a.request);IF NOT EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions later WHERE later.tenant_id=a.tenant_id AND later.txid=a.txid AND later.id<>a.id AND later.sealed AND later.request->'product_ids'=a.request->'product_ids' AND later.request->'warehouse_ids'=a.request->'warehouse_ids' AND later.before_frame=e.after_frame) AND f<>e.after_frame THEN RAISE EXCEPTION 'Zapieczętowany fizyczny efekt zmienił się' USING ERRCODE='23514';END IF;f:=e.after_frame;\n FOREACH kindj IN ARRAY ARRAY['stock','bin','layer'] LOOP keyj:=CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bin' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END;\n ids:=coalesce(e.proof->keyj,'[]');beforej:=a.before_frame->(kindj||'_journals');afterj:=f->(kindj||'_journals');\n IF EXISTS(SELECT FROM jsonb_array_elements(beforej)b WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(afterj)n WHERE n=b)) THEN RAISE EXCEPTION 'Historia fizyczna została zmieniona' USING ERRCODE='23514';END IF;\n SELECT coalesce(jsonb_agg(v->'id' ORDER BY v->>'id'),'[]') INTO news FROM jsonb_array_elements(afterj)v WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(beforej)o WHERE o->>'id'=v->>'id');\n IF news<>(SELECT coalesce(jsonb_agg(v ORDER BY v#>>'{}'),'[]') FROM jsonb_array_elements(ids)v) OR jsonb_array_length(ids)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(ids)v) THEN RAISE EXCEPTION 'Dowód nie obejmuje wszystkich rzeczywistych ruchów' USING ERRCODE='23514';END IF;END LOOP;\n -- Every signed cell delta equals the actual new journal sum, including net-zero SKU moves.\n FOREACH kindj IN ARRAY ARRAY['stock','bins','positions'] LOOP\n WITH old_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(a.before_frame->kindj)v),\n new_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(f->kindj)v),\n journals AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,sum((v->>'delta')::numeric) delta FROM jsonb_array_elements(f->(CASE kindj WHEN 'stock' THEN 'stock_journals' WHEN 'bins' THEN 'bin_journals' ELSE 'layer_journals' END))v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->(CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bins' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END))) GROUP BY 1,2,3,4),\n cells AS(SELECT coalesce(n.w,o.w) w,coalesce(n.p,o.p) p,coalesce(n.l,o.l) l,coalesce(n.layer,o.layer) layer,coalesce(n.q,0)-coalesce(o.q,0) delta FROM old_cells o FULL JOIN new_cells n USING(w,p,l,layer))\n SELECT count(*) INTO countj FROM cells c FULL JOIN journals j USING(w,p,l,layer) WHERE coalesce(c.delta,0)<>coalesce(j.delta,0);\n IF countj<>0 THEN RAISE EXCEPTION 'Ruch nie odpowiada dokładnemu stanowi komórki' USING ERRCODE='23514';END IF;END LOOP;\n IF a.source_kind IN('warehouse_document','purchase_receipt','wms_movement','wms_receipt') THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(a.tenant_id,(e.proof->>'warehouse_document_id')::uuid);IF d.id IS NULL OR d.status<>'posted' OR(a.source_kind='warehouse_document' AND d.id<>a.source_id) OR(a.number IS NOT NULL AND d.number<>a.number->>'number' AND NOT(a.source_kind='wms_movement' AND EXISTS(SELECT FROM public.wms_previews wp WHERE(wp.tenant_id,wp.id)=(a.tenant_id,a.source_id) AND wp.kind='adjustment'))) THEN RAISE EXCEPTION 'Brak rzeczywistego zaksięgowanego dokumentu' USING ERRCODE='23514';END IF;\n IF EXISTS(SELECT FROM jsonb_array_elements(f->'stock_journals')v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'stock_movement_ids')) AND v->>'warehouse_document_id' IS DISTINCT FROM d.id::text) THEN RAISE EXCEPTION 'Ruch obcego dokumentu' USING ERRCODE='23514';END IF;\n IF a.source_kind='purchase_receipt' AND NOT EXISTS(SELECT FROM public.purchase_receipts pr JOIN public.purchase_orders po ON(po.tenant_id,po.id)=(pr.tenant_id,pr.order_id) WHERE(pr.tenant_id,pr.id,pr.document_id)=(a.tenant_id,a.source_id,d.id) AND pr.id=e.purchase_receipt_id AND po.warehouse_id=d.warehouse_id AND NOT EXISTS(SELECT FROM public.purchase_receipt_lines l WHERE(l.tenant_id,l.receipt_id)=(pr.tenant_id,pr.id) AND NOT EXISTS(SELECT FROM public.warehouse_document_lines dl WHERE(dl.tenant_id,dl.document_id,dl.product_id,dl.quantity,dl.location)=(l.tenant_id,d.id,l.product_id,l.quantity,l.location)))) THEN RAISE EXCEPTION 'Dowód PZ nie odpowiada rzeczywistemu przyjęciu dostawy' USING ERRCODE='23514';END IF;\n IF a.source_kind IN('wms_movement','wms_receipt') THEN SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);IF op.id IS NULL OR op.warehouse_document_id IS DISTINCT FROM d.id OR(a.source_kind='wms_receipt' AND(op.kind<>'receipt' OR op.client_key<>a.source_id OR op.purchase_receipt_id IS NOT NULL)) OR(a.source_kind='wms_movement' AND op.request->>'preview_id' IS DISTINCT FROM a.source_id::text) THEN RAISE EXCEPTION 'Dokument nie odpowiada rzeczywistemu źródłu WMS' USING ERRCODE='23514';END IF;IF a.source_kind='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id)=(a.tenant_id,a.source_id);IF pv.id IS NULL OR pv.kind<>op.kind OR d.reference<>'WMS/'||pv.id OR d.warehouse_id<>(pv.request->>'warehouse_id')::uuid THEN RAISE EXCEPTION 'Obcy zapisany plan ruchu WMS' USING ERRCODE='23514';END IF;IF pv.kind='adjustment' AND e.proof->'correction_document' IS DISTINCT FROM public.catalog_stock_control_wms_correction_build(a.id,e.proof) THEN RAISE EXCEPTION 'Niepełny zapisany dokument PW/RW korekty' USING ERRCODE='23514';END IF;END IF;END IF;\n ELSIF a.source_kind='wms_opening' THEN\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(a.tenant_id,a.source_id,a.actor_id);\n  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);\n  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.policy_version<>0 OR op.id IS NULL\n   OR op.kind<>'opening' OR op.actor_id IS DISTINCT FROM a.actor_id OR op.policy_version<>1\n   OR op.request->>'preview_id' IS DISTINCT FROM pv.id::text OR op.request->>'scope_hash' IS DISTINCT FROM pv.scope_hash\n   OR op.request->'confirmed' IS DISTINCT FROM 'true'::jsonb\n   OR (pv.snapshot->'valuation'->>'unknown_quantity'<>'0' AND op.request->'ack_unknown_costs' IS DISTINCT FROM 'true'::jsonb)\n   OR NOT EXISTS(SELECT FROM public.wms_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,op.id) AND public.catalog_stock_control_owns_xmin(o.xmin))\n   OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL OR op.order_id IS NOT NULL OR op.return_id IS NOT NULL\n   OR e.warehouse_document_id IS NOT NULL OR e.location_operation_id IS NOT NULL OR a.number IS NOT NULL\n   OR a.before_frame->'stock'<>f->'stock' OR a.before_frame->'bins'<>f->'bins'\n   OR a.before_frame->'positions'<>'[]'::jsonb\n   OR e.proof->'stock_movement_ids'<>'[]'::jsonb OR e.proof->'location_movement_ids'<>'[]'::jsonb\n   OR NOT EXISTS(SELECT FROM public.wms_policies h WHERE h.tenant_id=a.tenant_id AND h.enabled AND h.version=1\n    AND h.method='FIFO' AND h.opening_operation_id=op.id AND h.currency=pv.request->>'currency' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))\n  THEN RAISE EXCEPTION 'Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF' USING ERRCODE='23514';END IF;\n  -- Every positive physical bin in the entire tenant, including nonstrict\n  -- catalogs, is represented once. Opening never writes stock or a second PZ.\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q\n    FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)\n  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;\n  IF countj<>0 THEN RAISE EXCEPTION 'Otwarcie nie obejmuje całego zapasu firmy' USING ERRCODE='23514';END IF;\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q,\n    r->>'lot_code' code,(r->>'unit_cost_minor')::bigint cost,r->>'currency' currency FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency\n    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)\n    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)\n    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin='opening'\n     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL\n     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))\n  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code\n    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;\n  IF countj<>0 OR jsonb_array_length(f->'positions')<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR jsonb_array_length(e.proof->'layer_movement_ids')<>jsonb_array_length(pv.snapshot->'rows')\n   OR EXISTS(SELECT FROM jsonb_array_elements(f->'layer_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'layer_movement_ids'))\n     AND(j->>'operation_id' IS DISTINCT FROM op.id::text OR j->>'kind'<>'opening' OR(j->>'delta')::integer<=0))\n  THEN RAISE EXCEPTION 'Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='inventory_import' THEN PERFORM public.catalog_stock_count_validate(eid);\n ELSIF a.source_kind='return' THEN PERFORM public.catalog_stock_return_validate(eid);\n ELSIF a.source_kind='dispatch' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego automatycznego WZ' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='stocktake' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego PW/RW' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='location_operation' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>'kind'='move') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->'bin_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'location_movement_ids')) AND j->>'operation_id' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->'stock')v WHERE coalesce((v->>'on_hand')::integer,0) IS DISTINCT FROM(SELECT(o->>'on_hand')::integer FROM jsonb_array_elements(a.before_frame->'stock')o WHERE(o->>'warehouse_id',o->>'product_id')=(v->>'warehouse_id',v->>'product_id'))) THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW; relokacja wymaga dowodu' USING ERRCODE='23514';END IF;\n ELSE RAISE EXCEPTION 'Źródło strict wymaga certyfikowanego adaptera dokumentu' USING ERRCODE='23514';END IF;END ","sha256":"aa3c54fdeee098fb147ae76b48d6197e03e16b162ff880ba0e1fd7c03847cace"},"catalog_stock_control_guards":{"body":" DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid='public.catalog_stock_control_guards()'::regprocedure);BEGIN\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace='public'::regnamespace AND p.proname IN('catalog_stock_control_xid_claim_guard','catalog_stock_control_capture_xid_birth'))<>13 OR\n  to_regprocedure('public.catalog_stock_control_owns_xmin(xid)') IS NULL OR\n  to_regprocedure('public.catalog_stock_control_prune_xid_claims()') IS NULL THEN RETURN false; END IF;\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'catalog_stock_control_%' AND relkind='r')<>14 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_control_%' AND c.relkind='r' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_control_%' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\n RETURN coalesce((SELECT fingerprint=public.catalog_stock_control_fingerprint() FROM public.catalog_stock_control_manifest WHERE id),false);END ","sha256":"71ae1c60ac7e99bc32e0175f59594d915dbfa6e9aef1a84bb0d349d36a5462b7"},"b2b_credit_fingerprint":{"body":"\n SELECT md5(jsonb_build_object(\n 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,\n 'acl',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a),\n 'cols',(SELECT jsonb_agg(jsonb_build_array(x.attname,format_type(x.atttypid,x.atttypmod),x.attnotnull,x.attgenerated,x.attidentity,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(ca.grantor),CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,ca.is_grantable) ORDER BY CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,pg_get_userbyid(ca.grantor)::text,ca.is_grantable) FROM aclexplode(x.attacl)ca),pg_get_expr(d.adbin,d.adrelid)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),\n 'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.convalidated,pg_get_constraintdef(k.oid,true)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),\n 'policies',(SELECT jsonb_agg(jsonb_build_array(po.polname,(SELECT array_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END) FROM unnest(po.polroles)x),po.polcmd,pg_get_expr(po.polqual,po.polrelid),pg_get_expr(po.polwithcheck,po.polrelid)) ORDER BY po.polname) FROM pg_policy po WHERE po.polrelid=c.oid),\n 'indexes',(SELECT jsonb_agg(jsonb_build_array(i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indrelid=c.oid),\n 'triggers',(SELECT jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid,true)) ORDER BY tr.tgname) FROM pg_trigger tr WHERE tr.tgrelid=c.oid AND NOT tr.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND (c.relname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR c.relname LIKE 'catalog\\_stock\\_return\\_%' ESCAPE '\\' OR c.relname LIKE 'catalog\\_stock\\_control\\_%' ESCAPE '\\' OR c.relname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR c.relname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR c.relname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\' OR c.relname IN('local_invoice_series','local_invoice_series_commands','orders','order_items','order_merge_claims','return_cases','documents','invoice_plans','odoo_invoice_exports','users','sessions','memberships','api_keys','account_security','workspace_security_policies','tenants','return_items','stock_movements','stock_location_movements','wms_layer_movements','wms_cost_layers','wms_issue_fragments','wms_return_fragments','wms_operations')) AND c.relkind IN('r','p')),\n 'functions',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.provolatile,p.proisstrict,p.proleakproof,p.proparallel,p.prokind,p.proretset,p.prorettype,pg_get_function_identity_arguments(p.oid),pg_get_function_result(p.oid),p.proargmodes,p.proargnames,pg_get_expr(p.proargdefaults,0),(SELECT lanname FROM pg_language WHERE oid=p.prolang),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND ((p.proname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR p.proname LIKE 'catalog\\_stock\\_return\\_%' ESCAPE '\\' OR p.proname LIKE 'catalog\\_stock\\_control\\_%' ESCAPE '\\' OR p.proname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR p.proname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR p.proname LIKE 'local\\_invoice\\_%' ESCAPE '\\' OR p.proname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\') OR p.oid IN(SELECT tr.tgfoid FROM pg_trigger tr JOIN pg_class rel ON rel.oid=tr.tgrelid WHERE rel.relnamespace='public'::regnamespace AND NOT tr.tgisinternal AND rel.relname IN('orders','order_items','order_merge_claims','return_cases','documents','invoice_plans','odoo_invoice_exports','users','sessions','memberships','api_keys','account_security','workspace_security_policies','tenants')))),\n 'documents_checks',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,pg_get_constraintdef(oid,true)) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.documents'::regclass AND conname IN('documents_kind_check','documents_proforma_local','documents_native_invoice')),\n 'document_indexes',(SELECT jsonb_agg(jsonb_build_array(c.relname,i.indisvalid,pg_get_indexdef(i.indexrelid)) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE c.relname IN('document_order_mode','document_demo_number')),\n 'parent_triggers',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid,true)) ORDER BY tgrelid::regclass::text,tgname) FROM pg_trigger WHERE tgfoid IN(SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR proname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR proname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR proname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\')))\n )::text) ","sha256":"eb63a87e7d4dd426474f7f9a4cc08c3acb5a482247f1fdf40dcc21f21015c948"}}$projectionold$::jsonb
 OR cert->'successor_functions' IS DISTINCT FROM $projectionnew${"catalog_stock_control_effect_prepare":{"body":"\nDECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;strictids jsonb;eid uuid:=gen_random_uuid();s public.catalog_stock_control_series;d public.warehouse_documents;w uuid;kindj text;yr integer:=extract(year FROM transaction_timestamp());n bigint;num jsonb;f jsonb;old public.catalog_stock_control_effect_admissions;pv public.wms_previews;\nBEGIN PERFORM public.catalog_stock_control_require();\n -- No public activation scopes are imposed on ordinary physical callers; their\n -- actual enclosing source IAM is enlisted by the trusted server adapter.\n IF uid IS NOT NULL AND NOT EXISTS(SELECT FROM public.memberships WHERE(tenant_id,user_id)=(t,uid) AND role IN('admin','operator')) THEN RAISE EXCEPTION 'Brak aktualnego operatora fizycznego efektu' USING ERRCODE='42501';END IF;\n IF b->>'source_kind' NOT IN('warehouse_document','purchase_receipt','dispatch','stocktake','location_operation','wms_movement','wms_receipt','return','wms_opening','catalog_import','inventory_import','manual_off_correction') THEN RAISE EXCEPTION 'Nieznane źródło fizyczne' USING ERRCODE='23514';END IF;\n\n IF b->>'source_kind'='manual_off_correction' AND NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma JOIN public.manual_inventory_off_previews mp ON(mp.tenant_id,mp.id)=(ma.tenant_id,ma.preview_id)\n WHERE(ma.tenant_id,ma.id,ma.actor_id)=(t,(b->>'source_id')::uuid,uid) AND ma.api_key_id IS NOT DISTINCT FROM kid AND ma.root_xid=pg_current_xact_id()\n AND b=jsonb_build_object('source_kind','manual_off_correction','source_id',ma.id,'product_ids',jsonb_build_array(mp.request->'product_id'),'warehouse_ids',jsonb_build_array(mp.request->'warehouse_id')))\n THEN RAISE EXCEPTION 'Manual strict source requires genuine managed parent' USING ERRCODE='23514';END IF;\n PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog.strict.lifecycle:'||t,0));\n SELECT coalesce(jsonb_agg(DISTINCT p.catalog_id ORDER BY p.catalog_id),'[]') INTO strictids FROM public.products p JOIN public.catalog_stock_control_policies h ON(h.tenant_id,h.catalog_id)=(p.tenant_id,p.catalog_id) WHERE p.tenant_id=t AND p.id IN(SELECT v::uuid FROM jsonb_array_elements_text(b->'product_ids')v);\n IF jsonb_array_length(strictids)=0 THEN RETURN NULL;END IF;\n FOR w IN SELECT v::uuid FROM jsonb_array_elements_text(b->'warehouse_ids')v ORDER BY v LOOP PERFORM public.warehouse_inventory_policy_lock(t,w);END LOOP;\n PERFORM pg_advisory_xact_lock(hashtextextended('catalog.strict.quota:'||t,0));\n SELECT * INTO old FROM public.catalog_stock_control_effect_admissions WHERE(tenant_id,source_kind,source_id)=(t,b->>'source_kind',(b->>'source_id')::uuid);\n IF old.id IS NOT NULL THEN IF old.sealed THEN RETURN NULL;END IF;IF old.txid<>pg_current_xact_id() OR old.actor_id IS DISTINCT FROM uid OR old.api_key_id IS DISTINCT FROM kid OR old.request<>b THEN RAISE EXCEPTION 'Inne przyjęcie fizycznego źródła' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('id',old.id,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',old.number);END IF;\n IF b->>'source_kind'='warehouse_document' THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(t,(b->>'source_id')::uuid);IF d.id IS NULL OR d.status<>'draft' THEN RAISE EXCEPTION 'Historyczne źródło nie otrzyma nowego numeru' USING ERRCODE='23514';END IF;kindj:=CASE d.kind WHEN 'receipt' THEN 'PZ' WHEN 'transfer' THEN 'MM' WHEN 'issue' THEN 'WZ' END;IF kindj IS NULL THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW' USING ERRCODE='23514';END IF;\n INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,d.warehouse_id,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;\n SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,d.warehouse_id,kindj) FOR UPDATE;\n n:=public.catalog_stock_control_next(t,s.id,yr);\n num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;\n IF b->>'source_kind' IN('purchase_receipt','wms_receipt') THEN SELECT v::uuid INTO w FROM jsonb_array_elements_text(b->'warehouse_ids')v;IF jsonb_array_length(b->'warehouse_ids')<>1 THEN RAISE EXCEPTION 'Przyjęcie dostawy ma jeden rzeczywisty magazyn' USING ERRCODE='23514';END IF;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,'PZ','PZ','PZ') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,'PZ') FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind','PZ','number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;\n IF b->>'source_kind'='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);IF pv.id IS NULL OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.kind NOT IN('issue','transfer','bin_move','adjustment') OR b->'product_ids'<>jsonb_build_array(pv.request->'product_id') OR b->'warehouse_ids'<>(SELECT jsonb_agg(v ORDER BY v#>>'{}') FROM jsonb_array_elements(jsonb_build_array(pv.request->'warehouse_id')||CASE WHEN pv.kind='transfer' THEN jsonb_build_array(pv.request->'destination_warehouse_id') ELSE '[]'::jsonb END)v) THEN RAISE EXCEPTION 'Brak własnego gotowego źródła ruchu WMS lub strict PW/RW' USING ERRCODE='23514';END IF;kindj:=CASE pv.kind WHEN 'issue' THEN 'WZ' WHEN 'transfer' THEN 'MM' WHEN 'adjustment' THEN CASE WHEN (pv.request->>'quantity')::integer>0 THEN 'PW' ELSE 'RW' END END;IF kindj IS NOT NULL THEN w:=(pv.request->>'warehouse_id')::uuid;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,kindj) FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object('kind',kindj,'number',s.prefix||'/'||yr||'/'||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,'0') END),'series_id',s.id,'year',yr,'sequence',n::text);END IF;END IF;\n IF b->>'source_kind'='wms_opening' AND EXISTS(SELECT FROM public.wms_operations o JOIN public.wms_policies h\n  ON(h.tenant_id,h.opening_operation_id)=(o.tenant_id,o.id) WHERE o.tenant_id=t AND o.kind='opening'\n  AND o.request->>'preview_id'=b->>'source_id') THEN RETURN NULL;END IF;\n IF b->>'source_kind'='wms_opening' THEN\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>'source_id')::uuid,uid);\n  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.policy_version<>0\n   OR b->'product_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'product_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)\n   OR b->'warehouse_ids' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>'warehouse_id' v FROM jsonb_array_elements(pv.snapshot->'rows')r)x)\n   OR EXISTS(SELECT FROM public.wms_policies WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_lots WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_cost_layers WHERE tenant_id=t)\n   OR EXISTS(SELECT FROM public.wms_layer_positions WHERE tenant_id=t)\n  THEN RAISE EXCEPTION 'Otwarcie strict wymaga własnego pełnego źródła WMS OFF' USING ERRCODE='23514';END IF;\n END IF;\n f:=public.catalog_stock_control_effect_frame(b);\n INSERT INTO public.catalog_stock_control_effect_admissions(id,tenant_id,actor_id,api_key_id,source_kind,source_id,request,before_frame,number) VALUES(eid,t,uid,kid,b->>'source_kind',(b->>'source_id')::uuid,b,f,num);\n RETURN jsonb_build_object('id',eid,'tenant_id',t,'source',b,'strict_catalog_ids',strictids,'number',num);END ","sha256":"79a6d5339095308abcbe89931ca6bdb23d14be33f36a75928a358e57b24a633f"},"catalog_stock_control_effect_validate":{"body":"\nDECLARE a public.catalog_stock_control_effect_admissions;e public.catalog_stock_control_effects;f jsonb;kindj text;keyj text;ids jsonb;news jsonb;beforej jsonb;afterj jsonb;x jsonb;priorj jsonb;delta numeric;sumdelta numeric;d public.warehouse_documents;op public.wms_operations;pv public.wms_previews;countj bigint;\nBEGIN SELECT * INTO a FROM public.catalog_stock_control_effect_admissions WHERE id=eid;IF a.id IS NULL OR a.txid<>pg_current_xact_id() THEN RAISE EXCEPTION 'Brak przyjęcia strict w bieżącej transakcji' USING ERRCODE='23514';END IF;SELECT * INTO e FROM public.catalog_stock_control_effects WHERE(tenant_id,admission_id)=(a.tenant_id,a.id);IF e.admission_id IS NULL THEN RAISE EXCEPTION 'Brak pełnego dokumentu fizycznego efektu' USING ERRCODE='23514';END IF;\n f:=public.catalog_stock_control_effect_frame(a.request);IF NOT EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions later WHERE later.tenant_id=a.tenant_id AND later.txid=a.txid AND later.id<>a.id AND later.sealed AND later.request->'product_ids'=a.request->'product_ids' AND later.request->'warehouse_ids'=a.request->'warehouse_ids' AND later.before_frame=e.after_frame) AND f<>e.after_frame THEN RAISE EXCEPTION 'Zapieczętowany fizyczny efekt zmienił się' USING ERRCODE='23514';END IF;f:=e.after_frame;\n FOREACH kindj IN ARRAY ARRAY['stock','bin','layer'] LOOP keyj:=CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bin' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END;\n ids:=coalesce(e.proof->keyj,'[]');beforej:=a.before_frame->(kindj||'_journals');afterj:=f->(kindj||'_journals');\n IF EXISTS(SELECT FROM jsonb_array_elements(beforej)b WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(afterj)n WHERE n=b)) THEN RAISE EXCEPTION 'Historia fizyczna została zmieniona' USING ERRCODE='23514';END IF;\n SELECT coalesce(jsonb_agg(v->'id' ORDER BY v->>'id'),'[]') INTO news FROM jsonb_array_elements(afterj)v WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(beforej)o WHERE o->>'id'=v->>'id');\n IF news<>(SELECT coalesce(jsonb_agg(v ORDER BY v#>>'{}'),'[]') FROM jsonb_array_elements(ids)v) OR jsonb_array_length(ids)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(ids)v) THEN RAISE EXCEPTION 'Dowód nie obejmuje wszystkich rzeczywistych ruchów' USING ERRCODE='23514';END IF;END LOOP;\n -- Every signed cell delta equals the actual new journal sum, including net-zero SKU moves.\n FOREACH kindj IN ARRAY ARRAY['stock','bins','positions'] LOOP\n WITH old_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(a.before_frame->kindj)v),\n new_cells AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,(v->>(CASE WHEN kindj='stock' THEN 'on_hand' ELSE 'quantity' END))::numeric q FROM jsonb_array_elements(f->kindj)v),\n journals AS(SELECT v->>'warehouse_id' w,v->>'product_id' p,CASE WHEN kindj='stock' THEN '' ELSE v->>'location' END l,CASE WHEN kindj='positions' THEN v->>'layer_id' ELSE '' END layer,sum((v->>'delta')::numeric) delta FROM jsonb_array_elements(f->(CASE kindj WHEN 'stock' THEN 'stock_journals' WHEN 'bins' THEN 'bin_journals' ELSE 'layer_journals' END))v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->(CASE kindj WHEN 'stock' THEN 'stock_movement_ids' WHEN 'bins' THEN 'location_movement_ids' ELSE 'layer_movement_ids' END))) GROUP BY 1,2,3,4),\n cells AS(SELECT coalesce(n.w,o.w) w,coalesce(n.p,o.p) p,coalesce(n.l,o.l) l,coalesce(n.layer,o.layer) layer,coalesce(n.q,0)-coalesce(o.q,0) delta FROM old_cells o FULL JOIN new_cells n USING(w,p,l,layer))\n SELECT count(*) INTO countj FROM cells c FULL JOIN journals j USING(w,p,l,layer) WHERE coalesce(c.delta,0)<>coalesce(j.delta,0);\n IF countj<>0 THEN RAISE EXCEPTION 'Ruch nie odpowiada dokładnemu stanowi komórki' USING ERRCODE='23514';END IF;END LOOP;\n IF a.source_kind IN('warehouse_document','purchase_receipt','wms_movement','wms_receipt') THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(a.tenant_id,(e.proof->>'warehouse_document_id')::uuid);IF d.id IS NULL OR d.status<>'posted' OR(a.source_kind='warehouse_document' AND d.id<>a.source_id) OR(a.number IS NOT NULL AND d.number<>a.number->>'number' AND NOT(a.source_kind='wms_movement' AND EXISTS(SELECT FROM public.wms_previews wp WHERE(wp.tenant_id,wp.id)=(a.tenant_id,a.source_id) AND wp.kind='adjustment'))) THEN RAISE EXCEPTION 'Brak rzeczywistego zaksięgowanego dokumentu' USING ERRCODE='23514';END IF;\n IF EXISTS(SELECT FROM jsonb_array_elements(f->'stock_journals')v WHERE v->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'stock_movement_ids')) AND v->>'warehouse_document_id' IS DISTINCT FROM d.id::text) THEN RAISE EXCEPTION 'Ruch obcego dokumentu' USING ERRCODE='23514';END IF;\n IF a.source_kind='purchase_receipt' AND NOT EXISTS(SELECT FROM public.purchase_receipts pr JOIN public.purchase_orders po ON(po.tenant_id,po.id)=(pr.tenant_id,pr.order_id) WHERE(pr.tenant_id,pr.id,pr.document_id)=(a.tenant_id,a.source_id,d.id) AND pr.id=e.purchase_receipt_id AND po.warehouse_id=d.warehouse_id AND NOT EXISTS(SELECT FROM public.purchase_receipt_lines l WHERE(l.tenant_id,l.receipt_id)=(pr.tenant_id,pr.id) AND NOT EXISTS(SELECT FROM public.warehouse_document_lines dl WHERE(dl.tenant_id,dl.document_id,dl.product_id,dl.quantity,dl.location)=(l.tenant_id,d.id,l.product_id,l.quantity,l.location)))) THEN RAISE EXCEPTION 'Dowód PZ nie odpowiada rzeczywistemu przyjęciu dostawy' USING ERRCODE='23514';END IF;\n IF a.source_kind IN('wms_movement','wms_receipt') THEN SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);IF op.id IS NULL OR op.warehouse_document_id IS DISTINCT FROM d.id OR(a.source_kind='wms_receipt' AND(op.kind<>'receipt' OR op.client_key<>a.source_id OR op.purchase_receipt_id IS NOT NULL)) OR(a.source_kind='wms_movement' AND op.request->>'preview_id' IS DISTINCT FROM a.source_id::text) THEN RAISE EXCEPTION 'Dokument nie odpowiada rzeczywistemu źródłu WMS' USING ERRCODE='23514';END IF;IF a.source_kind='wms_movement' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id)=(a.tenant_id,a.source_id);IF pv.id IS NULL OR pv.kind<>op.kind OR d.reference<>'WMS/'||pv.id OR d.warehouse_id<>(pv.request->>'warehouse_id')::uuid THEN RAISE EXCEPTION 'Obcy zapisany plan ruchu WMS' USING ERRCODE='23514';END IF;IF pv.kind='adjustment' AND e.proof->'correction_document' IS DISTINCT FROM public.catalog_stock_control_wms_correction_build(a.id,e.proof) THEN RAISE EXCEPTION 'Niepełny zapisany dokument PW/RW korekty' USING ERRCODE='23514';END IF;END IF;END IF;\n ELSIF a.source_kind='wms_opening' THEN\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(a.tenant_id,a.source_id,a.actor_id);\n  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);\n  IF pv.id IS NULL OR pv.kind<>'opening' OR NOT pv.ready OR pv.policy_version<>0 OR op.id IS NULL\n   OR op.kind<>'opening' OR op.actor_id IS DISTINCT FROM a.actor_id OR op.policy_version<>1\n   OR op.request->>'preview_id' IS DISTINCT FROM pv.id::text OR op.request->>'scope_hash' IS DISTINCT FROM pv.scope_hash\n   OR op.request->'confirmed' IS DISTINCT FROM 'true'::jsonb\n   OR (pv.snapshot->'valuation'->>'unknown_quantity'<>'0' AND op.request->'ack_unknown_costs' IS DISTINCT FROM 'true'::jsonb)\n   OR NOT EXISTS(SELECT FROM public.wms_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,op.id) AND public.catalog_stock_control_owns_xmin(o.xmin))\n   OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL OR op.order_id IS NOT NULL OR op.return_id IS NOT NULL\n   OR e.warehouse_document_id IS NOT NULL OR e.location_operation_id IS NOT NULL OR a.number IS NOT NULL\n   OR a.before_frame->'stock'<>f->'stock' OR a.before_frame->'bins'<>f->'bins'\n   OR a.before_frame->'positions'<>'[]'::jsonb\n   OR e.proof->'stock_movement_ids'<>'[]'::jsonb OR e.proof->'location_movement_ids'<>'[]'::jsonb\n   OR NOT EXISTS(SELECT FROM public.wms_policies h WHERE h.tenant_id=a.tenant_id AND h.enabled AND h.version=1\n    AND h.method='FIFO' AND h.opening_operation_id=op.id AND h.currency=pv.request->>'currency' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))\n  THEN RAISE EXCEPTION 'Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF' USING ERRCODE='23514';END IF;\n  -- Every positive physical bin in the entire tenant, including nonstrict\n  -- catalogs, is represented once. Opening never writes stock or a second PZ.\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q\n    FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)\n  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;\n  IF countj<>0 THEN RAISE EXCEPTION 'Otwarcie nie obejmuje całego zapasu firmy' USING ERRCODE='23514';END IF;\n  WITH expected AS(SELECT r->>'warehouse_id' w,r->>'product_id' p,r->>'location' l,(r->>'quantity')::integer q,\n    r->>'lot_code' code,(r->>'unit_cost_minor')::bigint cost,r->>'currency' currency FROM jsonb_array_elements(pv.snapshot->'rows')r),\n   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency\n    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)\n    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)\n    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin='opening'\n     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL\n     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))\n  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code\n    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;\n  IF countj<>0 OR jsonb_array_length(f->'positions')<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->'rows')\n   OR jsonb_array_length(e.proof->'layer_movement_ids')<>jsonb_array_length(pv.snapshot->'rows')\n   OR EXISTS(SELECT FROM jsonb_array_elements(f->'layer_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'layer_movement_ids'))\n     AND(j->>'operation_id' IS DISTINCT FROM op.id::text OR j->>'kind'<>'opening' OR(j->>'delta')::integer<=0))\n  THEN RAISE EXCEPTION 'Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='inventory_import' THEN PERFORM public.catalog_stock_count_validate(eid);\n ELSIF a.source_kind='return' THEN PERFORM public.catalog_stock_return_validate(eid);\n ELSIF a.source_kind='dispatch' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego automatycznego WZ' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='stocktake' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION 'Brak pełnego PW/RW' USING ERRCODE='23514';END IF;\n ELSIF a.source_kind='location_operation' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>'kind'='move') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->'bin_journals')j WHERE j->'id' IN(SELECT value FROM jsonb_array_elements(e.proof->'location_movement_ids')) AND j->>'operation_id' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->'stock')v WHERE coalesce((v->>'on_hand')::integer,0) IS DISTINCT FROM(SELECT(o->>'on_hand')::integer FROM jsonb_array_elements(a.before_frame->'stock')o WHERE(o->>'warehouse_id',o->>'product_id')=(v->>'warehouse_id',v->>'product_id'))) THEN RAISE EXCEPTION 'Pomiar strict wymaga PW/RW; relokacja wymaga dowodu' USING ERRCODE='23514';END IF;\n\n ELSIF a.source_kind='manual_off_correction' THEN\n IF e.proof<>jsonb_build_object('manual_receipt_id',a.source_id,'stock_movement_ids',jsonb_build_array((SELECT stock_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),\n 'location_movement_ids',jsonb_build_array((SELECT location_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),'layer_movement_ids','[]'::jsonb)\n OR a.number IS NOT NULL OR e.warehouse_document_id IS NOT NULL OR e.operation_id IS NOT NULL OR e.purchase_receipt_id IS NOT NULL OR e.dispatch_receipt_id IS NOT NULL OR e.adjustment_receipt_id IS NOT NULL OR e.location_operation_id IS NOT NULL\n OR NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma WHERE(ma.tenant_id,ma.id,ma.strict_effect_id,ma.actor_id)=(a.tenant_id,a.source_id,a.id,a.actor_id) AND ma.api_key_id IS NOT DISTINCT FROM a.api_key_id AND ma.root_xid=a.txid)\n THEN RAISE EXCEPTION 'Manual strict proof does not bind genuine parent' USING ERRCODE='23514';END IF;\n -- Parent validation excludes the strict-sealed predicate until effect_finish seals.\n PERFORM public.manual_inventory_off_validate(a.source_id,false);\n ELSE RAISE EXCEPTION 'Źródło strict wymaga certyfikowanego adaptera dokumentu' USING ERRCODE='23514';END IF;END ","sha256":"72a340b76487f8c5615720219741ed3d7faa4d486427db21b587a7036fd2ad99"},"catalog_stock_control_guards":{"body":" DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid='public.catalog_stock_control_guards()'::regprocedure);BEGIN\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace='public'::regnamespace AND p.proname IN('catalog_stock_control_xid_claim_guard','catalog_stock_control_capture_xid_birth'))<>13 OR\n  to_regprocedure('public.catalog_stock_control_owns_xmin(xid)') IS NULL OR\n  to_regprocedure('public.catalog_stock_control_prune_xid_claims()') IS NULL THEN RETURN false; END IF;\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'catalog_stock_control_%' AND relkind='r')<>14 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_control_%' AND c.relkind='r' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_control_%' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\n RETURN public.manual_inventory_off_valid();END ","sha256":"ef9c31fbabca36776256efe76dcd16265c9f742ce4a64cbd7cc000c056baf225"},"b2b_credit_fingerprint":{"body":"\n SELECT CASE WHEN public.manual_inventory_off_projection_valid() THEN (SELECT md5(jsonb_build_object(\n 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,\n 'acl',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a),\n 'cols',(SELECT jsonb_agg(jsonb_build_array(x.attname,format_type(x.atttypid,x.atttypmod),x.attnotnull,x.attgenerated,x.attidentity,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(ca.grantor),CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,ca.is_grantable) ORDER BY CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,pg_get_userbyid(ca.grantor)::text,ca.is_grantable) FROM aclexplode(x.attacl)ca),pg_get_expr(d.adbin,d.adrelid)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),\n 'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.convalidated,pg_get_constraintdef(k.oid,true)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),\n 'policies',(SELECT jsonb_agg(jsonb_build_array(po.polname,(SELECT array_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END) FROM unnest(po.polroles)x),po.polcmd,pg_get_expr(po.polqual,po.polrelid),pg_get_expr(po.polwithcheck,po.polrelid)) ORDER BY po.polname) FROM pg_policy po WHERE po.polrelid=c.oid),\n 'indexes',(SELECT jsonb_agg(jsonb_build_array(i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indrelid=c.oid),\n 'triggers',(SELECT jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid,true)) ORDER BY tr.tgname) FROM pg_trigger tr WHERE tr.tgrelid=c.oid AND NOT tr.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND (c.relname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR c.relname LIKE 'catalog\\_stock\\_return\\_%' ESCAPE '\\' OR c.relname LIKE 'catalog\\_stock\\_control\\_%' ESCAPE '\\' OR c.relname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR c.relname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR c.relname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\' OR c.relname IN('local_invoice_series','local_invoice_series_commands','orders','order_items','order_merge_claims','return_cases','documents','invoice_plans','odoo_invoice_exports','users','sessions','memberships','api_keys','account_security','workspace_security_policies','tenants','return_items','stock_movements','stock_location_movements','wms_layer_movements','wms_cost_layers','wms_issue_fragments','wms_return_fragments','wms_operations')) AND c.relkind IN('r','p')),\n 'functions',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,public.manual_inventory_off_projected_definition(p.oid),pg_get_userbyid(p.proowner),p.provolatile,p.proisstrict,p.proleakproof,p.proparallel,p.prokind,p.proretset,p.prorettype,pg_get_function_identity_arguments(p.oid),pg_get_function_result(p.oid),p.proargmodes,p.proargnames,pg_get_expr(p.proargdefaults,0),(SELECT lanname FROM pg_language WHERE oid=p.prolang),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND ((p.proname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR p.proname LIKE 'catalog\\_stock\\_return\\_%' ESCAPE '\\' OR p.proname LIKE 'catalog\\_stock\\_control\\_%' ESCAPE '\\' OR p.proname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR p.proname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR p.proname LIKE 'local\\_invoice\\_%' ESCAPE '\\' OR p.proname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\') OR p.oid IN(SELECT tr.tgfoid FROM pg_trigger tr JOIN pg_class rel ON rel.oid=tr.tgrelid WHERE rel.relnamespace='public'::regnamespace AND NOT tr.tgisinternal AND rel.relname IN('orders','order_items','order_merge_claims','return_cases','documents','invoice_plans','odoo_invoice_exports','users','sessions','memberships','api_keys','account_security','workspace_security_policies','tenants')))),\n 'documents_checks',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,pg_get_constraintdef(oid,true)) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.documents'::regclass AND conname IN('documents_kind_check','documents_proforma_local','documents_native_invoice')),\n 'document_indexes',(SELECT jsonb_agg(jsonb_build_array(c.relname,i.indisvalid,pg_get_indexdef(i.indexrelid)) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE c.relname IN('document_order_mode','document_demo_number')),\n 'parent_triggers',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid,true)) ORDER BY tgrelid::regclass::text,tgname) FROM pg_trigger WHERE tgfoid IN(SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'b2b\\_credit\\_%' ESCAPE '\\' OR proname LIKE 'b2b\\_invoice\\_%' ESCAPE '\\' OR proname LIKE 'fa3\\_draft\\_%' ESCAPE '\\' OR proname LIKE 'b2b\\_dropship\\_%' ESCAPE '\\')))\n )::text)) ELSE NULL END\n","sha256":"9e3766d47014f65190e470b4aa4ac70d54bc96ce094493408480a41026564a0b"}}$projectionnew$::jsonb
